/* Déclic — Notions fondamentales : algèbre linéaire (1) — espaces vectoriels, sous-espaces, bases */
(()=>{
/* ---------- helpers locaux ---------- */
const V2=(x,y)=>`(${fmt(x)} ; ${fmt(y)})`;
const V3=(x,y,z)=>`(${fmt(x)} ; ${fmt(y)} ; ${fmt(z)})`;
// droite vectorielle dirigée par (dx ; dy), tracée d’un bord à l’autre
const ln=(P,dx,dy,q={})=>P.seg(-30*dx,-30*dy,30*dx,30*dy,Object.assign({c:'var(--ok)',w:2,dash:true},q));
// Figure « a·u + b·v » dans le plan : u (bleu), v (jaune), a·u puis b·v mis bout à bout, résultat (accent)
function comb(u,v,a,b,o={}){
  const R=o.r||6, P=plane({x:[-R,R],y:[-R,R],lab:2});
  const au=[a*u[0],a*u[1]], bv=[b*v[0],b*v[1]], w=[au[0]+bv[0],au[1]+bv[1]];
  if(o.lines){ ln(P,u[0],u[1],{c:'var(--math)',w:1.5,op:.5}); ln(P,v[0],v[1],{c:'var(--spark)',w:1.5,op:.5}); }
  if(o.para&&(a||b)) P.poly([[0,0],au,w,bv],{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5,dash:true});
  if(a) P.arrow(0,0,au[0],au[1],{c:'var(--math)',w:3,op:.45});
  if(b) P.arrow(au[0],au[1],w[0],w[1],{c:'var(--spark)',w:3,op:.45});
  P.arrow(0,0,u[0],u[1],{c:'var(--math)',w:3}); P.arrow(0,0,v[0],v[1],{c:'var(--spark)',w:3});
  if(a||b) P.arrow(0,0,w[0],w[1],{c:'var(--accent)',w:4});
  P.text(u[0],u[1],'u',{c:'var(--math)',dx:7,dy:-6}); P.text(v[0],v[1],'v',{c:'var(--spark)',dx:7,dy:-6});
  if(o.target) P.dot(o.target[0],o.target[1],{c:'var(--bad)',l:o.tl||'cible',dx:o.tdx??9});
  return P;
}
// Somme u + v avec le parallélogramme, et λ·v
function somme(u,v,lam){
  const P=plane({x:[-6,6],y:[-6,6],lab:2});
  if(lam!==undefined&&lam!==0) P.arrow(0,0,lam*v[0],lam*v[1],{c:'var(--spark)',w:7,op:.25});
  P.poly([[0,0],u,[u[0]+v[0],u[1]+v[1]],v],{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5,dash:true});
  P.arrow(0,0,u[0],u[1],{c:'var(--math)',w:3}).arrow(0,0,v[0],v[1],{c:'var(--spark)',w:3});
  if(u[0]+v[0]||u[1]+v[1]) P.arrow(0,0,u[0]+v[0],u[1]+v[1],{c:'var(--accent)',w:4});
  P.text(u[0],u[1],'u',{c:'var(--math)',dx:7,dy:-6}); if(v[0]||v[1]) P.text(v[0],v[1],'v',{c:'var(--spark)',dx:7,dy:-6});
  if(u[0]+v[0]||u[1]+v[1]) P.text(u[0]+v[0],u[1]+v[1],'u + v',{c:'var(--accent)',dx:7,dy:-6});
  return P;
}
// Plan Vect(u, v) dans l’espace, avec le vecteur a·u + b·v
function plan3(u,v,a,b){
  const S=space({r:5.2,az:28,el:22}), m=(p,k)=>p.map(c=>c*k), add=(p,q)=>p.map((c,i)=>c+q[i]);
  const K=1.6, corners=[add(m(u,-K),m(v,-K)),add(m(u,K),m(v,-K)),add(m(u,K),m(v,K)),add(m(u,-K),m(v,K))];
  S.poly(corners,{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5});
  for(let k=-1;k<=1;k+=.5){ S.seg(add(m(u,k),m(v,-K)),add(m(u,k),m(v,K)),{c:'var(--line)',w:1}); S.seg(add(m(u,-K),m(v,k)),add(m(u,K),m(v,k)),{c:'var(--line)',w:1}); }
  const w=add(m(u,a),m(v,b));
  if(a) S.arrow([0,0,0],m(u,a),{c:'var(--math)',w:3,op:.45}); if(b) S.arrow(m(u,a),w,{c:'var(--spark)',w:3,op:.45});
  S.arrow([0,0,0],u,{c:'var(--math)',w:3}).arrow([0,0,0],v,{c:'var(--spark)',w:3});
  if(a||b) S.arrow([0,0,0],w,{c:'var(--accent)',w:4});
  S.text(u,'u',{c:'var(--math)',dx:6,dy:-6}).text(v,'v',{c:'var(--spark)',dx:6,dy:-6}); S.dot([0,0,0],{r:4,c:'var(--ink)'});
  return S.svg();
}
// Courbe de a·f + b·g pour deux fonctions
function fcomb(f,g,a,b,o={}){
  const P=plane({x:o.x||[-3,3],y:o.y||[-4,6],lab:2});
  P.fn(f,{c:'var(--math)',w:2,op:.6}).fn(g,{c:'var(--spark)',w:2,op:.6}).fn(x=>a*f(x)+b*g(x),{c:'var(--accent)',w:4});
  return P;
}
const Rappel=s=>`<div class="blk" data-t="Rappel"><p>${s}</p></div>`;

COURS.push(
/* ===================== 1. LE PLAN ℝ² ===================== */
{subj:'gred',sem:'lin',id:'gred-ev-plan',h:'Le plan ℝ², premier espace vectoriel',p:'Pourquoi on additionne des vecteurs et on les multiplie par des nombres, les règles de calcul dans ℝ² vérifiées une à une, le parallélogramme et l’étirement, les combinaisons a·u + b·v et les droites vectorielles.',steps:[
  {h:'Pourquoi une structure pour les vecteurs ?',
   p:'<p>Trois situations qui n’ont rien à voir en apparence. Deux forces tirent sur un anneau : leur effet total est une seule force, la <b>résultante</b>, diagonale du parallélogramme construit sur les deux flèches. Un randonneur marche 3 km vers l’est puis 4 km vers le nord : son <b>déplacement</b> total est une flèche de 5 km. Enfin, si deux couples (<i>x</i> ; <i>y</i>) et (<i>x</i>′ ; <i>y</i>′) vérifient tous deux l’équation 2<i>x</i> − <i>y</i> = 0, leur somme la vérifie aussi, et le double de chacun aussi.</p><div class="idea"><p>Dans les trois cas, on fait exactement deux choses avec les objets : on les <b>additionne</b>, et on les <b>multiplie par un nombre réel</b> (doubler une force, parcourir la moitié du chemin, prendre trois fois une solution). Et dans les trois cas, ces deux opérations obéissent aux mêmes règles. L’algèbre linéaire étudie cette structure commune une fois pour toutes, au lieu de la redécouvrir à chaque nouvelle situation.</p></div><p>On commence par l’exemple le plus concret, le plan ℝ², où un vecteur est à la fois un couple de nombres et une flèche. Tout ce qu’on y vérifiera à la main servira ensuite de modèle pour la définition générale.</p>',
   fig:(()=>{ const P=plane({x:[-1,7],y:[-1,5],lab:1}); P.poly([[0,0],[4,1],[5,4],[1,3]],{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5,dash:true});
     P.arrow(0,0,4,1,{c:'var(--math)',w:3}).arrow(0,0,1,3,{c:'var(--spark)',w:3}).arrow(0,0,5,4,{c:'var(--accent)',w:4});
     P.text(4,1,'F₁',{c:'var(--math)',dx:6,dy:14}).text(1,3,'F₂',{c:'var(--spark)',dx:-22,dy:-4}).text(5,4,'F₁ + F₂',{c:'var(--accent)',dx:6,dy:-4}); P.dot(0,0,{r:5,c:'var(--ink)'}); return P.svg(); })(),
   note:'Un vecteur n’est pas une flèche plantée à un endroit précis : deux flèches de même longueur, même direction et même sens représentent le même vecteur. C’est pourquoi on peut toujours le faire partir de l’origine, et le repérer par le point où il arrive.'},
  {h:'ℝ² : addition et multiplication par un réel',
   p:'<p>Un <b>vecteur du plan</b> est un couple de réels <b>u</b> = (<i>x</i> ; <i>y</i>) : on le dessine comme la flèche qui part de l’origine et arrive au point de coordonnées (<i>x</i> ; <i>y</i>). L’ensemble de ces couples se note ℝ² (lire « R deux »). Deux opérations y sont définies.</p><div class="def"><p>Pour <b>u</b> = (<i>x</i> ; <i>y</i>), <b>v</b> = (<i>x</i>′ ; <i>y</i>′) et λ ∈ ℝ :<br><b>u</b> + <b>v</b> = (<i>x</i> + <i>x</i>′ ; <i>y</i> + <i>y</i>′) (<b>addition</b>, loi interne) ;<br>λ · <b>u</b> = (λ<i>x</i> ; λ<i>y</i>) (<b>multiplication par un réel</b>, dite <b>loi externe</b>, car λ n’est pas un vecteur).<br>Le <b>vecteur nul</b> est <b>0</b> = (0 ; 0) et l’<b>opposé</b> de <b>u</b> est −<b>u</b> = (−<i>x</i> ; −<i>y</i>).</p></div><div class="idea"><p>Tout se fait <b>coordonnée par coordonnée</b>. Le nombre λ s’appelle un <b>scalaire</b> : il « met à l’échelle » le vecteur. On écrit souvent λ<b>u</b> sans le point.</p></div><div class="ex"><p>(2 ; −1) + (3 ; 4) = (5 ; 3). 3 · (2 ; −1) = (6 ; −3). −(2 ; −1) = (−2 ; 1). Et (2 ; −1) + (−2 ; 1) = (0 ; 0) = <b>0</b>.</p></div><div class="warn"><p>Il n’y a <b>pas</b> de multiplication d’un vecteur par un vecteur dans cette structure. (2 ; −1) · (3 ; 4) n’a aucun sens ici. Un scalaire multiplie un vecteur, un vecteur s’ajoute à un vecteur, c’est tout.</p></div>'},
  {h:'Parallélogramme et étirement',
   p:'<p>Géométriquement, <b>u</b> + <b>v</b> est la <b>diagonale du parallélogramme</b> construit sur <b>u</b> et <b>v</b> : on met la flèche <b>v</b> bout à bout après <b>u</b>, et on arrive au même point qu’en mettant <b>u</b> après <b>v</b>. Multiplier <b>v</b> par λ <b>étire</b> la flèche d’un facteur |λ| sans changer sa direction, et la retourne si λ &lt; 0. Ici <b>u</b> = (3 ; 1) est fixé. Règle <b>v</b> et λ.</p>',
   params:[{id:'x',l:'v₁',min:-3,max:3,v:-1},{id:'y',l:'v₂',min:-3,max:3,v:2},{id:'l',l:'λ',min:-2,max:2,step:.5,v:1.5}],
   draw:v=>somme([3,1],[v.x,v.y],v.l).svg(),
   info:v=>`<b>u</b> + <b>v</b> = ${V2(3+v.x,1+v.y)} ; λ · <b>v</b> = ${fmt(v.l)} · ${V2(v.x,v.y)} = ${V2(v.l*v.x,v.l*v.y)} (flèche jaune pâle).`,
   note:'Quand v est sur la même droite que u, le parallélogramme s’aplatit : la somme reste sur cette droite. Et −1 · v est le vecteur de même longueur en sens opposé : c’est l’opposé −v.'},
  {h:'(ℝ², +) est un groupe abélien',
   p:Rappel('Un <b>groupe abélien</b> est un ensemble muni d’une loi interne associative, commutative, avec un neutre, et où chaque élément a un symétrique.')+'<div class="prop"><p>L’addition de ℝ² est associative, commutative, admet <b>0</b> = (0 ; 0) pour neutre, et tout vecteur <b>u</b> a pour opposé −<b>u</b>. Autrement dit, <b>(ℝ², +) est un groupe abélien</b>.</p></div><div class="why"><p>Chaque règle se vérifie coordonnée par coordonnée, et se ramène à la même règle pour les nombres réels. Commutativité : <b>u</b> + <b>v</b> = (<i>x</i> + <i>x</i>′ ; <i>y</i> + <i>y</i>′) = (<i>x</i>′ + <i>x</i> ; <i>y</i>′ + <i>y</i>) = <b>v</b> + <b>u</b>, parce que <i>x</i> + <i>x</i>′ = <i>x</i>′ + <i>x</i> dans ℝ. Associativité : (<b>u</b> + <b>v</b>) + <b>w</b> a pour première coordonnée (<i>x</i> + <i>x</i>′) + <i>x</i>″ = <i>x</i> + (<i>x</i>′ + <i>x</i>″), celle de <b>u</b> + (<b>v</b> + <b>w</b>). Neutre : <b>u</b> + <b>0</b> = (<i>x</i> + 0 ; <i>y</i> + 0) = <b>u</b>. Symétrique : <b>u</b> + (−<b>u</b>) = (<i>x</i> − <i>x</i> ; <i>y</i> − <i>y</i>) = <b>0</b>.</p></div><div class="idea"><p>ℝ² hérite des règles de ℝ parce que ses opérations sont « deux copies » de celles de ℝ. Cette idée reviendra pour ℝⁿ, les polynômes, les fonctions.</p></div><div class="ex"><p>Avec <b>u</b> = (1 ; 2), <b>v</b> = (3 ; −1), <b>w</b> = (0 ; 4) : (<b>u</b> + <b>v</b>) + <b>w</b> = (4 ; 1) + (0 ; 4) = (4 ; 5) et <b>u</b> + (<b>v</b> + <b>w</b>) = (1 ; 2) + (3 ; 3) = (4 ; 5).</p></div>',
   note:'Conséquence : on peut simplifier (u + w = v + w ⇒ u = v), et l’équation u + x = v a l’unique solution x = v − u, c’est-à-dire v + (−u).'},
  {h:'Les règles de la multiplication par un réel',
   p:'<p>La loi externe a ses propres règles, qui disent comment elle s’accorde avec l’addition des vecteurs et avec les opérations sur les nombres.</p><div class="prop"><p>Pour tous <b>u</b>, <b>v</b> ∈ ℝ² et λ, μ ∈ ℝ :<br>(1) λ · (<b>u</b> + <b>v</b>) = λ · <b>u</b> + λ · <b>v</b> ;<br>(2) (λ + μ) · <b>u</b> = λ · <b>u</b> + μ · <b>u</b> ;<br>(3) (λμ) · <b>u</b> = λ · (μ · <b>u</b>) ;<br>(4) 1 · <b>u</b> = <b>u</b>.</p></div><div class="why"><p>Encore coordonnée par coordonnée. (1) : la première coordonnée de λ(<b>u</b> + <b>v</b>) est λ(<i>x</i> + <i>x</i>′) = λ<i>x</i> + λ<i>x</i>′, celle de λ<b>u</b> + λ<b>v</b> : c’est la distributivité dans ℝ. (2) : (λ + μ)<i>x</i> = λ<i>x</i> + μ<i>x</i>, même raison. (3) : (λμ)<i>x</i> = λ(μ<i>x</i>) par associativité du produit des réels. (4) : 1 · <i>x</i> = <i>x</i>.</p></div><div class="idea"><p>Les règles (1) et (2) sont deux <b>distributivités</b> : la première par rapport à l’addition des vecteurs, la seconde par rapport à l’addition des nombres. Ce sont deux « plus » différents, même s’ils s’écrivent pareil. La règle (3) dit qu’étirer de μ puis de λ revient à étirer de λμ.</p></div><div class="ex"><p>2 · ((1 ; 3) + (2 ; −1)) = 2 · (3 ; 2) = (6 ; 4), et 2 · (1 ; 3) + 2 · (2 ; −1) = (2 ; 6) + (4 ; −2) = (6 ; 4). De même (2 + 3) · (1 ; 3) = (5 ; 15) = (2 ; 6) + (3 ; 9).</p></div>',
   note:'Avec (2) et (4) on retrouve l’opposé : u + (−1) · u = (1 + (−1)) · u = 0 · u = (0 ; 0). Donc (−1) · u = −u.'},
  {h:'Quelle règle ?',p:'Pour calculer 3 · ((2 ; 1) + (−1 ; 4)), on écrit 3 · (2 ; 1) + 3 · (−1 ; 4). Quelle règle utilise-t-on&nbsp;?',
   opts:['La distributivité de λ par rapport à l’addition des vecteurs : λ(<b>u</b> + <b>v</b>) = λ<b>u</b> + λ<b>v</b>','La distributivité par rapport à l’addition des nombres : (λ + μ)<b>u</b> = λ<b>u</b> + μ<b>u</b>','La règle (λμ)<b>u</b> = λ(μ<b>u</b>)','La commutativité de l’addition'],ans:0,
   why:'Le même scalaire 3 se distribue sur la somme de deux vecteurs : c’est la règle (1). Les deux membres valent (3 ; 15).'},
  {h:'Un calcul coordonnée par coordonnée',p:'Soit <b>u</b> = (2 ; −3) et <b>v</b> = (−1 ; 4). Quelle est la deuxième coordonnée de 3<b>u</b> − 2<b>v</b>&nbsp;?',lab:'deuxième coordonnée =',ans:-17,
   why:'3u = (6 ; −9) et 2v = (−2 ; 8), donc 3u − 2v = (6 + 2 ; −9 − 8) = (8 ; −17).'},
  {h:'La combinaison a·u + b·v',
   p:'<p>On fixe deux vecteurs <b>u</b> = (2 ; 1) et <b>v</b> = (−1 ; 2). Avec deux scalaires <i>a</i> et <i>b</i>, on forme le vecteur <i>a</i>·<b>u</b> + <i>b</i>·<b>v</b> : on étire <b>u</b> de <i>a</i>, <b>v</b> de <i>b</i>, puis on additionne. On dit que c’est une <b>combinaison linéaire</b> de <b>u</b> et <b>v</b>, de coefficients <i>a</i> et <i>b</i>. Déplace les curseurs et observe le point d’arrivée.</p>',
   params:[{id:'a',l:'a',min:-3,max:3,step:.5,v:1},{id:'b',l:'b',min:-3,max:3,step:.5,v:1}],
   draw:v=>comb([2,1],[-1,2],v.a,v.b,{para:true,lines:true}).svg(),
   info:v=>`${fmt(v.a)} · (2 ; 1) + ${fmt(v.b)} · (−1 ; 2) = ${V2(2*v.a,v.a)} + ${V2(-v.b,2*v.b)} = <b>${V2(2*v.a-v.b,v.a+2*v.b)}</b>.`,
   note:'Les deux droites pâles sont les directions de u et de v : le point d’arrivée se lit comme dans un quadrillage penché. En faisant varier a et b dans tout ℝ, on atteint chaque point du plan, et une seule fois. C’est ce qu’on démontrera plus bas.'},
  {kind:'Pratique',h:'Atteins la cible',p:'Toujours avec <b>u</b> = (2 ; 1) et <b>v</b> = (−1 ; 2), règle <i>a</i> et <i>b</i> pour que <i>a</i>·<b>u</b> + <i>b</i>·<b>v</b> soit exactement le point rouge (4 ; 7).',
   params:[{id:'a',l:'a',min:-3,max:3,step:.5,v:1},{id:'b',l:'b',min:-3,max:3,step:.5,v:1}],
   draw:v=>comb([2,1],[-1,2],v.a,v.b,{para:true,lines:true,target:[4,7],tl:'(4 ; 7)',r:8}).svg(),
   info:v=>`<i>a</i>·<b>u</b> + <i>b</i>·<b>v</b> = ${V2(2*v.a-v.b,v.a+2*v.b)}`,
   ok:v=>v.a===3&&v.b===2,
   why:'Il faut 2a − b = 4 et a + 2b = 7. La première donne b = 2a − 4 ; dans la seconde : a + 4a − 8 = 7, donc a = 3, puis b = 2. Contrôle : 3(2 ; 1) + 2(−1 ; 2) = (6 − 2 ; 3 + 4) = (4 ; 7).'},
  {kind:'Méthode',h:'Écrire un vecteur comme combinaison de deux autres',
   p:'<b>Quand :</b> on cherche <i>a</i> et <i>b</i> tels que <i>a</i><b>u</b> + <i>b</i><b>v</b> = <b>w</b>. <b>Pourquoi ça marche :</b> deux vecteurs sont égaux exactement quand leurs deux coordonnées le sont ; l’égalité vectorielle devient donc un <b>système de deux équations</b> à deux inconnues <i>a</i>, <i>b</i>. <b>Comment :</b> 1) écris l’égalité coordonnée par coordonnée ; 2) résous le système (substitution ou combinaison des lignes) ; 3) recalcule <i>a</i><b>u</b> + <i>b</i><b>v</b> pour contrôler. Si le système n’a pas de solution, <b>w</b> n’est pas une combinaison de <b>u</b> et <b>v</b> ; cela arrive quand <b>u</b> et <b>v</b> sont sur une même droite.',
   demo:{enonce:'Écris <b>w</b> = (3 ; 11) comme combinaison de <b>u</b> = (1 ; 2) et <b>v</b> = (−1 ; 3). Puis essaie d’écrire (1 ; 0) avec <b>u</b> = (1 ; 2) et <b>v</b>′ = (2 ; 4).',
    etapes:[{f:'<i>a</i>(1 ; 2) + <i>b</i>(−1 ; 3) = (<i>a</i> − <i>b</i> ; 2<i>a</i> + 3<i>b</i>) = (3 ; 11).',w:'On calcule la combinaison avec des lettres.'},
     {f:'Système : <i>a</i> − <i>b</i> = 3 et 2<i>a</i> + 3<i>b</i> = 11.',w:'Une équation par coordonnée.'},
     {f:'<i>a</i> = 3 + <i>b</i>, puis 2(3 + <i>b</i>) + 3<i>b</i> = 11, soit 5<i>b</i> = 5 : <i>b</i> = 1 et <i>a</i> = 4.',w:'Substitution.'},
     {f:'Contrôle : 4(1 ; 2) + 1(−1 ; 3) = (4 − 1 ; 8 + 3) = (3 ; 11).',w:'On recalcule toujours.'},
     {f:'Second cas : <i>a</i> + 2<i>b</i> = 1 et 2<i>a</i> + 4<i>b</i> = 0. La seconde ligne est le double de la première, mais 0 ≠ 2 : aucune solution.',w:'v′ = 2u : les deux vecteurs sont sur une même droite, et leurs combinaisons y restent. (1 ; 0) n’y est pas.'}],
    conclusion:'<b>w</b> = 4<b>u</b> + <b>v</b>. En revanche (1 ; 0) n’est pas une combinaison de <b>u</b> et <b>v</b>′ = 2<b>u</b> : toutes leurs combinaisons sont de la forme (<i>a</i> + 2<i>b</i>)<b>u</b>, donc sur la droite de <b>u</b>.'}},
  {h:'Applique la méthode',p:'Avec <b>u</b> = (2 ; 1) et <b>v</b> = (1 ; −1), on écrit <b>w</b> = (7 ; −1) sous la forme <i>a</i><b>u</b> + <i>b</i><b>v</b>. Que vaut <i>a</i>&nbsp;?',lab:'a =',ans:2,
   why:'2a + b = 7 et a − b = −1. En additionnant : 3a = 6, donc a = 2, puis b = 3. Contrôle : 2(2 ; 1) + 3(1 ; −1) = (7 ; −1).'},
  {h:'Droites vectorielles',
   p:'<p>Que dessinent tous les multiples d’un même vecteur ? Pour <b>u</b> = (2 ; 1), les vecteurs λ<b>u</b> = (2λ ; λ) ont tous leur extrémité sur la droite qui passe par l’origine et par (2 ; 1). Déplace λ.</p><div class="def"><p>Si <b>u</b> ≠ <b>0</b>, l’ensemble ℝ<b>u</b> = {λ<b>u</b> : λ ∈ ℝ} est la <b>droite vectorielle</b> dirigée par <b>u</b>. Deux vecteurs sont <b>colinéaires</b> si l’un est un multiple de l’autre.</p></div><div class="prop"><p>Une droite vectorielle est <b>stable</b> par les deux opérations : si <b>v</b>, <b>w</b> ∈ ℝ<b>u</b> alors <b>v</b> + <b>w</b> ∈ ℝ<b>u</b> et μ<b>v</b> ∈ ℝ<b>u</b>. Elle contient <b>0</b>.</p></div><div class="why"><p>Si <b>v</b> = λ<b>u</b> et <b>w</b> = λ′<b>u</b>, alors <b>v</b> + <b>w</b> = (λ + λ′)<b>u</b> par la règle (2), et μ<b>v</b> = (μλ)<b>u</b> par la règle (3). Enfin <b>0</b> = 0 · <b>u</b>.</p></div><div class="ex"><p>(6 ; −4) ∈ ℝ(−3 ; 2), car (6 ; −4) = −2 · (−3 ; 2). Mais (3 ; 2) ∉ ℝ(−3 ; 2) : il faudrait λ = −1 pour la première coordonnée et λ = 1 pour la seconde.</p></div>',
   params:[{id:'l',l:'λ',min:-2.5,max:2.5,step:.5,v:1.5}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); ln(P,2,1,{c:'var(--ok)',w:2.5}); if(v.l) P.arrow(0,0,2*v.l,v.l,{c:'var(--accent)',w:4}); P.arrow(0,0,2,1,{c:'var(--math)',w:3}); P.text(2,1,'u',{c:'var(--math)',dx:6,dy:14}); P.dot(2*v.l,v.l,{r:5,c:'var(--accent)',l:'λu',dx:8,dy:-8}); return P.svg(); },
   info:v=>`λ · <b>u</b> = ${fmt(v.l)} · (2 ; 1) = ${V2(2*v.l,v.l)}${v.l===0?' : le vecteur nul est sur la droite.':v.l<0?' : λ &lt; 0 retourne la flèche, mais on reste sur la droite.':'.'}`,
   note:'Pour tester si (x ; y) est colinéaire à (u₁ ; u₂), on compare les rapports : il faut x·u₂ = y·u₁. Pour (6 ; −4) et (−3 ; 2) : 6 · 2 = (−4) · (−3) = 12, oui.'},
  {h:'Sur la même droite ?',p:'Lequel de ces vecteurs appartient à la droite vectorielle ℝ(2 ; −3)&nbsp;?',
   opts:['(3 ; −2)','(−4 ; 6)','(4 ; 6)','(0 ; 1)'],ans:1,
   why:'(−4 ; 6) = −2 · (2 ; −3). Pour les autres, aucun λ ne convient : (3 ; −2) donnerait λ = 1,5 puis λ = 2/3 ; (4 ; 6) donnerait λ = 2 puis λ = −2 ; (0 ; 1) donnerait λ = 0 puis λ = −1/3.'},
  {h:'Deux vecteurs non colinéaires engendrent le plan',
   p:'<p>La figure à curseurs le laissait voir : avec <b>u</b> = (2 ; 1) et <b>v</b> = (−1 ; 2), on atteint chaque point du plan. C’est général.</p><div class="thm"><p>Si <b>u</b> = (<i>u</i>₁ ; <i>u</i>₂) et <b>v</b> = (<i>v</i>₁ ; <i>v</i>₂) ne sont pas colinéaires, c’est-à-dire si <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ ≠ 0, alors tout vecteur <b>w</b> de ℝ² s’écrit <b>d’une seule façon</b> <b>w</b> = <i>a</i><b>u</b> + <i>b</i><b>v</b>.</p></div><div class="why"><p>Le système <i>a</i><i>u</i>₁ + <i>b</i><i>v</i>₁ = <i>w</i>₁, <i>a</i><i>u</i>₂ + <i>b</i><i>v</i>₂ = <i>w</i>₂ se résout par combinaison : on multiplie la première ligne par <i>v</i>₂, la seconde par <i>v</i>₁, et on soustrait. Il reste <i>a</i>(<i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁) = <i>w</i>₁<i>v</i>₂ − <i>w</i>₂<i>v</i>₁. Comme le nombre <i>D</i> = <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ n’est pas nul, on peut diviser : <i>a</i> est imposé, et de même <i>b</i> = (<i>u</i>₁<i>w</i>₂ − <i>u</i>₂<i>w</i>₁)/<i>D</i>. Un seul couple (<i>a</i> ; <i>b</i>) convient, et il convient vraiment (on le vérifie en remplaçant).</p></div><div class="idea"><p>Le nombre <i>D</i> est le déterminant de la matrice de colonnes <b>u</b> et <b>v</b>. S’il est nul, les deux lignes du système sont proportionnelles : il y a soit aucune solution, soit une infinité. Les vecteurs <b>u</b> et <b>v</b> forment alors un « quadrillage aplati ».</p></div><div class="ex"><p>Pour <b>u</b> = (2 ; 1), <b>v</b> = (−1 ; 2) : <i>D</i> = 2 · 2 − 1 · (−1) = 5 ≠ 0. Pour <b>w</b> = (4 ; 7) : <i>a</i> = (4 · 2 − 7 · (−1))/5 = 3 et <i>b</i> = (2 · 7 − 1 · 4)/5 = 2, comme dans la pratique.</p></div>',
   note:'Ce théorème dit qu’un couple (u, v) non colinéaire joue dans le plan le même rôle que les deux axes : chaque vecteur a des « coordonnées » (a ; b) dans ce nouveau quadrillage. C’est l’idée de base, qu’on reverra en toute dimension.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:'<div class="keep"><ul><li>ℝ² est l’ensemble des couples (<i>x</i> ; <i>y</i>). Addition : (<i>x</i> ; <i>y</i>) + (<i>x</i>′ ; <i>y</i>′) = (<i>x</i> + <i>x</i>′ ; <i>y</i> + <i>y</i>′). Multiplication par un réel : λ(<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; λ<i>y</i>). Tout se fait coordonnée par coordonnée.</li><li>(ℝ², +) est un groupe abélien : associativité, commutativité, neutre <b>0</b> = (0 ; 0), opposé −<b>u</b>. Chaque règle vient de la règle correspondante dans ℝ.</li><li>Quatre règles pour la loi externe : λ(<b>u</b> + <b>v</b>) = λ<b>u</b> + λ<b>v</b>, (λ + μ)<b>u</b> = λ<b>u</b> + μ<b>u</b>, (λμ)<b>u</b> = λ(μ<b>u</b>), 1<b>u</b> = <b>u</b>.</li><li>Géométrie : <b>u</b> + <b>v</b> est la diagonale du parallélogramme ; λ<b>u</b> étire <b>u</b> d’un facteur |λ| et le retourne si λ &lt; 0.</li><li>Combinaison linéaire <i>a</i><b>u</b> + <i>b</i><b>v</b> : pour atteindre <b>w</b>, on résout le système coordonnée par coordonnée.</li><li>Droite vectorielle ℝ<b>u</b> = {λ<b>u</b>} : stable par + et par les scalaires, contient <b>0</b>. (<i>x</i> ; <i>y</i>) ∈ ℝ(<i>u</i>₁ ; <i>u</i>₂) ⇔ <i>x</i><i>u</i>₂ = <i>y</i><i>u</i>₁.</li><li>Si <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ ≠ 0, tout vecteur du plan s’écrit d’une seule façon <i>a</i><b>u</b> + <i>b</i><b>v</b>.</li></ul></div>'},
  {kind:'Problème',h:'Équilibrer un anneau',
   p:'Trois cordes tirent sur un anneau. La première exerce la force <b>F</b>₁ = <i>a</i>·<b>u</b> avec <b>u</b> = (3 ; 1), la deuxième <b>F</b>₂ = <i>b</i>·<b>v</b> avec <b>v</b> = (−1 ; 2), où <i>a</i> et <i>b</i> sont les tensions réglables (en newtons par unité). La troisième corde tire avec <b>w</b> = (−7 ; −7), fixe. L’anneau est immobile quand la somme des trois forces est le vecteur nul.',
   fig:(()=>{ const P=comb([3,1],[-1,2],0,0,{r:8,lines:true}); P.arrow(0,0,-7,-7,{c:'var(--bad)',w:3}); P.text(-7,-7,'w',{c:'var(--bad)',dx:-16,dy:4}); return P.svg(); })(),
   parts:[
    {q:'a) Quelle est la deuxième coordonnée de <b>u</b> + <b>v</b>&nbsp;?',lab:'deuxième coordonnée =',ans:3,hint:'On additionne coordonnée par coordonnée.',why:'u + v = (3 − 1 ; 1 + 2) = (2 ; 3).'},
    {q:'b) L’équilibre s’écrit <i>a</i><b>u</b> + <i>b</i><b>v</b> + <b>w</b> = <b>0</b>, soit <i>a</i><b>u</b> + <i>b</i><b>v</b> = (7 ; 7). Que vaut <i>a</i>&nbsp;?',lab:'a =',ans:3,hint:'Écris le système : 3a − b = 7 et a + 2b = 7.',why:'b = 3a − 7, puis a + 6a − 14 = 7, donc 7a = 21 et a = 3.'},
    {q:'c) Que vaut <i>b</i>&nbsp;?',lab:'b =',ans:2,hint:'Reporte a = 3 dans b = 3a − 7.',why:'b = 9 − 7 = 2. Contrôle : 3(3 ; 1) + 2(−1 ; 2) = (9 − 2 ; 3 + 4) = (7 ; 7).'},
    {q:'d) On remplace la troisième corde par <b>w</b>′ = (−6 ; −2). Que se passe-t-il&nbsp;?',opts:['Aucun réglage ne permet l’équilibre','L’équilibre demande <i>a</i> = 2 et <i>b</i> = 0 : la deuxième corde ne sert plus à rien','L’équilibre demande <i>a</i> = 0 et <i>b</i> = 3','Il y a plusieurs réglages possibles'],ans:1,
     hint:'Remarque que (6 ; 2) est colinéaire à u.',why:'(6 ; 2) = 2u, donc a = 2 et b = 0 conviennent. Comme u et v ne sont pas colinéaires (3 · 2 − 1 · (−1) = 7 ≠ 0), c’est l’unique solution.'},
   ],
   sol:'L’équilibre impose <i>a</i><b>u</b> + <i>b</i><b>v</b> = −<b>w</b> = (7 ; 7). Coordonnée par coordonnée : 3<i>a</i> − <i>b</i> = 7 et <i>a</i> + 2<i>b</i> = 7.<br>De la première, <i>b</i> = 3<i>a</i> − 7 ; dans la seconde, 7<i>a</i> − 14 = 7, d’où <b><i>a</i> = 3</b> et <b><i>b</i> = 2</b>. Contrôle : 3(3 ; 1) + 2(−1 ; 2) = (7 ; 7).<br>Avec <b>w</b>′ = (−6 ; −2), il faut <i>a</i><b>u</b> + <i>b</i><b>v</b> = (6 ; 2) = 2<b>u</b> : <i>a</i> = 2, <i>b</i> = 0. Le déterminant 3 · 2 − 1 · (−1) = 7 est non nul, donc cette écriture est unique : la deuxième corde doit être relâchée.'},
  {kind:'Problème',h:'Les solutions d’une équation forment une droite',
   p:'On note <i>S</i> l’ensemble des couples (<i>x</i> ; <i>y</i>) ∈ ℝ² qui vérifient 3<i>x</i> + 2<i>y</i> = 0, et <i>S</i>′ l’ensemble de ceux qui vérifient 3<i>x</i> + 2<i>y</i> = 6. On veut montrer que <i>S</i> est une droite vectorielle, trouver un vecteur qui la dirige, et comprendre pourquoi <i>S</i>′ ne se comporte pas du tout pareil.',
   fig:(()=>{ const P=plane({x:[-5,5],y:[-5,5],lab:2}); ln(P,2,-3,{c:'var(--ok)',w:2.5}); P.fn(x=>(6-3*x)/2,{c:'var(--bad)',w:2.5,dash:true}); P.arrow(0,0,2,-3,{c:'var(--math)',w:3}); P.text(2,-3,'(2 ; −3)',{c:'var(--math)',dx:6,dy:4}); P.text(-4,4.4,'3x + 2y = 0',{c:'var(--ok)',s:12}).text(0.4,3.6,'3x + 2y = 6',{c:'var(--bad)',s:12}); return P.svg(); })(),
   parts:[
    {q:'a) Quel est l’élément de <i>S</i> dont la première coordonnée vaut 4&nbsp;? Donne sa deuxième coordonnée.',lab:'y =',ans:-6,hint:'Remplace x par 4 dans 3x + 2y = 0.',why:'12 + 2y = 0 donne y = −6. Le couple (4 ; −6) est dans S.'},
    {q:'b) Pourquoi la somme de deux éléments de <i>S</i> est-elle encore dans <i>S</i>&nbsp;?',opts:['Parce que S contient (0 ; 0)','Parce que 3(<i>x</i> + <i>x</i>′) + 2(<i>y</i> + <i>y</i>′) = (3<i>x</i> + 2<i>y</i>) + (3<i>x</i>′ + 2<i>y</i>′) = 0 + 0','Parce que l’addition de ℝ² est commutative','Parce que S est infini'],ans:1,
     hint:'Calcule 3(x + x′) + 2(y + y′) en regroupant les termes de chaque couple.',why:'On regroupe les termes pour faire apparaître les deux équations connues, qui valent 0. Le même calcul avec λ montre que λ(x ; y) ∈ S.'},
    {q:'c) Tout élément de <i>S</i> s’écrit λ(2 ; −3). Pour (10 ; −15), que vaut λ&nbsp;?',lab:'λ =',ans:5,hint:'Compare la première coordonnée : 2λ = 10.',why:'λ = 5, et 5 · (−3) = −15 confirme. Réciproquement, si 3x + 2y = 0, alors y = −3x/2 et (x ; y) = (x/2)(2 ; −3) : S est bien la droite vectorielle ℝ(2 ; −3).'},
    {q:'d) Soit (<i>x</i> ; <i>y</i>) et (<i>x</i>′ ; <i>y</i>′) deux éléments de <i>S</i>′. Que vaut 3(<i>x</i> + <i>x</i>′) + 2(<i>y</i> + <i>y</i>′)&nbsp;?',lab:'valeur =',ans:12,hint:'Même regroupement qu’en b), mais chaque équation vaut 6.',why:'6 + 6 = 12 ≠ 6 : la somme sort de S′. S′ n’est pas stable par addition, et d’ailleurs (0 ; 0) ∉ S′ : c’est une droite, mais pas une droite vectorielle.'},
   ],
   sol:'Stabilité de <i>S</i> : si 3<i>x</i> + 2<i>y</i> = 0 et 3<i>x</i>′ + 2<i>y</i>′ = 0, alors 3(<i>x</i> + <i>x</i>′) + 2(<i>y</i> + <i>y</i>′) = 0 et 3(λ<i>x</i>) + 2(λ<i>y</i>) = λ · 0 = 0. De plus (0 ; 0) ∈ <i>S</i>.<br>Description : 3<i>x</i> + 2<i>y</i> = 0 ⇔ <i>y</i> = −3<i>x</i>/2 ⇔ (<i>x</i> ; <i>y</i>) = (<i>x</i>/2)(2 ; −3). Donc <b><i>S</i> = ℝ(2 ; −3)</b>, droite vectorielle dirigée par (2 ; −3). Pour (10 ; −15), λ = 5 ; pour <i>x</i> = 4, le point est (4 ; −6).<br>Pour <i>S</i>′ : la somme de deux solutions vérifie 3<i>x</i> + 2<i>y</i> = 12, pas 6, et (0 ; 0) ∉ <i>S</i>′. <i>S</i>′ est la droite <i>S</i> translatée de (2 ; 0) : une droite du plan, mais pas une droite vectorielle. Les équations <b>homogènes</b> (second membre nul) donnent des ensembles stables, les autres non.'},
]},
);

COURS.push(
/* ===================== 2. ESPACE VECTORIEL RÉEL : LES AXIOMES ===================== */
{subj:'gred',sem:'lin',id:'gred-espace-vectoriel',h:'Espace vectoriel réel : les axiomes',p:'La définition complète d’un espace vectoriel, le rôle de chaque axiome, les premières conséquences démontrées (0·v = 0, (−1)·v = −v), une galerie d’exemples vérifiés (ℝⁿ, polynômes, fonctions, suites, matrices) et des contre-exemples.',steps:[
  {h:'Du plan à la structure',
   p:'<p>Dans ℝ², on a vérifié huit règles de calcul, toutes héritées de ℝ coordonnée par coordonnée. Or beaucoup d’autres ensembles se manipulent exactement de la même façon. Deux polynômes s’additionnent et se multiplient par un réel : 2(<i>x</i>² + 1) + 3(<i>x</i> − 1) = 2<i>x</i>² + 3<i>x</i> − 1. Deux fonctions aussi : (2 sin + 3 cos)(<i>x</i>) = 2 sin <i>x</i> + 3 cos <i>x</i>. Deux matrices, deux suites, deux solutions d’une équation homogène : même chose.</p><div class="idea"><p>Plutôt que de revérifier les huit règles pour chaque nouvel ensemble, on fait l’inverse : on <b>pose les règles comme axiomes</b>, et on appelle <b>espace vectoriel</b> tout ensemble qui les satisfait. Tout théorème démontré à partir des seuls axiomes vaut alors d’un coup pour ℝ², pour les polynômes, pour les fonctions, pour les suites… C’est le même mouvement qui a conduit des exemples de symétries à la notion de groupe.</p></div><div class="ex"><p>Les trois objets (3 ; 1), 3<i>x</i>² + 1 et la fonction <i>t</i> ↦ 3 sin <i>t</i> + cos <i>t</i> n’ont rien de commun en apparence. Pourtant les écrire comme « 3 fois ceci plus 1 fois cela » est le même geste, et les calculs qui suivent obéissent aux mêmes règles.</p></div>',
   fig:(()=>{ const P=plane({x:[0,12],y:[0,4.6],grid:false,axes:false}); const box=(x,t,s)=>{ P.rect(x-1.75,1.6,3.5,2.2,{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5}); P.text(x,3.1,t,{a:'middle',s:13}); P.text(x,2.2,s,{a:'middle',s:11,c:'var(--muted)'}); };
     box(2,'ℝ²','(x ; y)'); box(6,'ℝ[x]','polynômes'); box(10,'F(ℝ, ℝ)','fonctions'); P.text(6,0.6,'mêmes règles : + et λ·',{a:'middle',s:12,c:'var(--accent)'}); P.seg(2,1.5,6,0.9,{c:'var(--line)',w:1.5}).seg(6,1.5,6,0.9,{c:'var(--line)',w:1.5}).seg(10,1.5,6,0.9,{c:'var(--line)',w:1.5}); return P.svg(); })(),
   note:'« Vecteur » ne veut plus dire « flèche » : c’est le nom d’un élément d’un espace vectoriel, quel qu’il soit. Un polynôme ou une fonction sont des vecteurs dans leur espace.'},
  {h:'Définition : espace vectoriel réel',
   p:'<div class="def"><p>Un <b>espace vectoriel réel</b> est un ensemble <i>E</i> muni d’une loi interne + et d’une loi externe · : ℝ × <i>E</i> → <i>E</i>, (λ ; <b>v</b>) ↦ λ·<b>v</b>, telles que :<br><b>(G)</b> (<i>E</i>, +) est un groupe abélien, de neutre noté <b>0</b> (vecteur nul) ;<br><b>(EV1)</b> λ·(<b>u</b> + <b>v</b>) = λ·<b>u</b> + λ·<b>v</b> ;<br><b>(EV2)</b> (λ + μ)·<b>u</b> = λ·<b>u</b> + μ·<b>u</b> ;<br><b>(EV3)</b> (λμ)·<b>u</b> = λ·(μ·<b>u</b>) ;<br><b>(EV4)</b> 1·<b>u</b> = <b>u</b> ;<br>pour tous <b>u</b>, <b>v</b> ∈ <i>E</i> et λ, μ ∈ ℝ. Les éléments de <i>E</i> sont les <b>vecteurs</b>, les réels sont les <b>scalaires</b>.</p></div><div class="idea"><p>Le groupe abélien regroupe quatre exigences (associativité, commutativité, neutre, opposés) : avec les quatre axiomes de la loi externe, cela fait huit règles, exactement celles vérifiées dans ℝ². « Loi externe » signifie que l’un des deux opérandes, λ, vient de l’extérieur de <i>E</i>. Le résultat λ·<b>v</b> doit toujours retomber dans <i>E</i>.</p></div><div class="ex"><p>ℝ² est un espace vectoriel : c’est ce que le chapitre précédent a vérifié. ℝ lui-même aussi, avec son addition et son produit (un réel est à la fois scalaire et vecteur). Et {<b>0</b>}, l’ensemble réduit au seul vecteur nul, en est un, le plus petit possible.</p></div><div class="warn"><p>Le même symbole + désigne deux additions : celle des vecteurs et celle des scalaires. Dans (EV2), le + de gauche est celui de ℝ, celui de droite est celui de <i>E</i>. Lis chaque formule en te demandant : qui est un nombre, qui est un vecteur ?</p></div>'},
  {h:'Pourquoi ces axiomes et pas d’autres ?',
   p:'<p>Pourquoi exiger 1·<b>u</b> = <b>u</b>, qui semble évident ? Parce que sans lui, une « multiplication » qui ne fait rien passerait le test.</p><div class="why"><p>Sur ℝ², définis λ ⊙ <b>u</b> = <b>0</b> pour tous λ et <b>u</b>. Alors (EV1) tient : λ ⊙ (<b>u</b> + <b>v</b>) = <b>0</b> = <b>0</b> + <b>0</b>. (EV2) aussi : (λ + μ) ⊙ <b>u</b> = <b>0</b> = <b>0</b> + <b>0</b>. (EV3) aussi : (λμ) ⊙ <b>u</b> = <b>0</b> = λ ⊙ <b>0</b>. Mais 1 ⊙ <b>u</b> = <b>0</b> ≠ <b>u</b>. L’axiome (EV4) est le seul qui oblige la loi externe à <b>agir vraiment</b> : il relie le scalaire 1 à l’identité.</p></div><div class="idea"><p>Chaque axiome a un rôle. (EV1) et (EV2) sont les deux distributivités : elles permettent de développer et de factoriser, donc de calculer comme avec des nombres. (EV3) permet d’enchaîner les étirements. (EV4) ancre l’échelle. Et le groupe abélien garantit qu’on peut simplifier et résoudre <b>u</b> + <b>x</b> = <b>v</b>.</p></div><div class="blk" data-t="Remarque"><p>La commutativité de + est en fait une conséquence des autres axiomes. Développe (1 + 1)·(<b>u</b> + <b>v</b>) de deux façons : par (EV1) puis (EV2), on obtient <b>u</b> + <b>v</b> + <b>u</b> + <b>v</b> ; par (EV2) puis (EV1), <b>u</b> + <b>u</b> + <b>v</b> + <b>v</b>. En simplifiant par <b>u</b> à gauche et par <b>v</b> à droite (règles de groupe), il reste <b>v</b> + <b>u</b> = <b>u</b> + <b>v</b>. On la garde quand même dans la définition, par clarté.</p></div>',
   note:'On pourrait remplacer ℝ par ℚ, par ℂ ou par n’importe quel corps K : on parle alors d’espace vectoriel sur K. Dans tout ce cours, les scalaires sont réels.'},
  {h:'Premières conséquences : 0·v = 0 et λ·0 = 0',
   p:'<p>Les axiomes ne disent pas ce que vaut 0·<b>v</b>. Dans ℝ², c’est (0 ; 0), mais dans un espace vectoriel abstrait il faut le <b>démontrer</b>, à partir des axiomes seulement.</p><div class="prop"><p>Dans tout espace vectoriel : <b>0·<b>v</b> = <b>0</b></b> pour tout vecteur <b>v</b>, et <b>λ·<b>0</b> = <b>0</b></b> pour tout scalaire λ. (Le premier 0 est le nombre, les autres sont le vecteur nul.)</p></div><div class="why"><p>Pour la première : 0 = 0 + 0 dans ℝ, donc 0·<b>v</b> = (0 + 0)·<b>v</b> = 0·<b>v</b> + 0·<b>v</b> par (EV2). On a donc <b>a</b> = <b>a</b> + <b>a</b> avec <b>a</b> = 0·<b>v</b>. On ajoute l’opposé de <b>a</b> aux deux membres (il existe, car (<i>E</i>, +) est un groupe) : <b>0</b> = <b>a</b>. Pour la seconde : <b>0</b> = <b>0</b> + <b>0</b> dans <i>E</i>, donc λ·<b>0</b> = λ·(<b>0</b> + <b>0</b>) = λ·<b>0</b> + λ·<b>0</b> par (EV1), et le même argument de simplification donne λ·<b>0</b> = <b>0</b>.</p></div><div class="idea"><p>La ruse est la même deux fois : écrire le zéro comme 0 + 0, distribuer, puis simplifier dans le groupe. Les deux distributivités servent chacune une fois.</p></div><div class="ex"><p>Dans l’espace des fonctions, 0·<i>f</i> est la fonction <i>x</i> ↦ 0 · <i>f</i>(<i>x</i>) = 0 : la fonction nulle, qui est bien le vecteur nul. La preuve générale le garantit sans ce calcul.</p></div>'},
  {h:'(−1)·v = −v, et quand λ·v est nul',
   p:'<div class="prop"><p>Dans tout espace vectoriel : <b>(−1)·<b>v</b> = −<b>v</b></b>, l’opposé de <b>v</b> dans le groupe (<i>E</i>, +). Et <b>λ·<b>v</b> = <b>0</b> ⇒ λ = 0 ou <b>v</b> = <b>0</b></b>.</p></div><div class="why"><p>Première règle : <b>v</b> + (−1)·<b>v</b> = 1·<b>v</b> + (−1)·<b>v</b> par (EV4), = (1 + (−1))·<b>v</b> par (EV2), = 0·<b>v</b> = <b>0</b> par la propriété précédente. Donc (−1)·<b>v</b> est un symétrique de <b>v</b> pour +. Comme dans un groupe le symétrique est unique, (−1)·<b>v</b> = −<b>v</b>.<br>Seconde règle : supposons λ·<b>v</b> = <b>0</b> et λ ≠ 0. Alors 1/λ existe dans ℝ, et <b>v</b> = 1·<b>v</b> = ((1/λ)λ)·<b>v</b> = (1/λ)·(λ·<b>v</b>) par (EV3), = (1/λ)·<b>0</b> = <b>0</b>. Donc si λ ≠ 0, nécessairement <b>v</b> = <b>0</b>.</p></div><div class="idea"><p>La seconde règle est l’analogue de « un produit de réels est nul si et seulement si un facteur est nul ». Elle repose sur le fait que tout scalaire non nul a un inverse : c’est pour cela que les scalaires forment un <b>corps</b>.</p></div><div class="warn"><p>On ne « divise » jamais par un vecteur. Pour isoler <b>v</b> dans λ·<b>v</b> = <b>w</b> avec λ ≠ 0, on multiplie par le scalaire 1/λ, comme dans la preuve : <b>v</b> = (1/λ)·<b>w</b>.</p></div>',
   note:'Autre conséquence utile : λ·(−v) = −(λ·v) = (−λ)·v, car λ·(−v) = λ·((−1)·v) = (λ·(−1))·v = (−λ)·v. On peut donc écrire −λv sans ambiguïté.'},
  {h:'Quel axiome dans la preuve ?',p:'Dans la preuve de 0·<b>v</b> = <b>0</b>, on écrit 0·<b>v</b> = (0 + 0)·<b>v</b> = 0·<b>v</b> + 0·<b>v</b>. Quel axiome justifie la dernière égalité&nbsp;?',
   opts:['(EV1) : λ·(<b>u</b> + <b>v</b>) = λ·<b>u</b> + λ·<b>v</b>','(EV2) : (λ + μ)·<b>u</b> = λ·<b>u</b> + μ·<b>u</b>','(EV3) : (λμ)·<b>u</b> = λ·(μ·<b>u</b>)','La commutativité de l’addition'],ans:1,
   why:'Le + de (0 + 0) est une somme de scalaires : c’est la distributivité par rapport à l’addition des nombres, (EV2), avec λ = μ = 0.'},
  {h:'ℝⁿ et les matrices 2 × 2',
   p:'<div class="ex"><p><b>ℝⁿ.</b> Les <i>n</i>-uplets (<i>x</i>₁ ; … ; <i>x</i>ₙ) de réels, avec l’addition et la multiplication coordonnée par coordonnée : (<i>x</i>₁ ; … ; <i>x</i>ₙ) + (<i>y</i>₁ ; … ; <i>y</i>ₙ) = (<i>x</i>₁ + <i>y</i>₁ ; … ; <i>x</i>ₙ + <i>y</i>ₙ) et λ(<i>x</i>₁ ; … ; <i>x</i>ₙ) = (λ<i>x</i>₁ ; … ; λ<i>x</i>ₙ). Vecteur nul (0 ; … ; 0), opposé (−<i>x</i>₁ ; … ; −<i>x</i>ₙ). Pour <i>n</i> = 3 : 2(1 ; 0 ; −2) + (0 ; 3 ; 1) = (2 ; 3 ; −3).</p></div><div class="ex"><p><b>Matrices 2 × 2.</b> L’ensemble M₂(ℝ) des matrices '+mat([['<i>a</i>','<i>b</i>'],['<i>c</i>','<i>d</i>']])+' avec l’addition case par case et λ·<i>A</i> = matrice des λ<i>a</i>, λ<i>b</i>, λ<i>c</i>, λ<i>d</i>. Vecteur nul : la matrice nulle. Par exemple 2·'+mat([[1,0],[3,'−1']])+' + '+mat([[0,2],[1,1]])+' = '+mat([[2,2],[7,'−1']])+'.</p></div><div class="why"><p>Dans les deux cas, les huit axiomes se vérifient composante par composante, exactement comme dans ℝ² : chaque égalité entre vecteurs se lit comme <i>n</i> (ou 4) égalités entre réels, toutes vraies parce que ℝ est un corps. Une matrice 2 × 2 n’est d’ailleurs qu’un 4-uplet rangé en carré : pour la structure d’espace vectoriel, M₂(ℝ) et ℝ⁴ se comportent de la même manière.</p></div><div class="warn"><p>Le produit de matrices ne fait pas partie de la structure d’espace vectoriel. On ne multiplie pas deux vecteurs entre eux ; on multiplie un vecteur par un scalaire.</p></div>'},
  {h:'Polynômes, fonctions et suites',
   p:'<div class="ex"><p><b>Polynômes.</b> ℝ[<i>x</i>] est l’ensemble des polynômes à coefficients réels. On additionne en regroupant les termes de même degré, et λ·<i>P</i> multiplie chaque coefficient : 2(<i>x</i>² + 1) + 3(<i>x</i> − 1) = 2<i>x</i>² + 3<i>x</i> − 1. Le vecteur nul est le polynôme nul. Les polynômes de degré au plus <i>n</i>, notés ℝ[<i>x</i>]≤ₙ, forment aussi un espace vectoriel : la somme de deux polynômes de degré ≤ <i>n</i> reste de degré ≤ <i>n</i>.</p></div><div class="ex"><p><b>Fonctions.</b> F(ℝ, ℝ) est l’ensemble des fonctions de ℝ dans ℝ. On définit <i>f</i> + <i>g</i> et λ<i>f</i> <b>point par point</b> : (<i>f</i> + <i>g</i>)(<i>x</i>) = <i>f</i>(<i>x</i>) + <i>g</i>(<i>x</i>) et (λ<i>f</i>)(<i>x</i>) = λ<i>f</i>(<i>x</i>). Le vecteur nul est la fonction nulle <i>x</i> ↦ 0, et −<i>f</i> est <i>x</i> ↦ −<i>f</i>(<i>x</i>).</p></div><div class="ex"><p><b>Suites.</b> Une suite réelle (<i>u</i>ₙ) est une fonction de ℕ dans ℝ : (<i>u</i>ₙ) + (<i>v</i>ₙ) = (<i>u</i>ₙ + <i>v</i>ₙ) et λ(<i>u</i>ₙ) = (λ<i>u</i>ₙ). C’est le cas F(ℕ, ℝ).</p></div><div class="why"><p>Vérifions (EV1) pour les fonctions : pour tout <i>x</i>, (λ(<i>f</i> + <i>g</i>))(<i>x</i>) = λ(<i>f</i>(<i>x</i>) + <i>g</i>(<i>x</i>)) = λ<i>f</i>(<i>x</i>) + λ<i>g</i>(<i>x</i>) = (λ<i>f</i> + λ<i>g</i>)(<i>x</i>). Les deux fonctions prennent la même valeur en chaque point, donc sont égales. Chaque axiome se vérifie ainsi, en se ramenant en chaque point <i>x</i> à la règle correspondante dans ℝ. Un polynôme étant déterminé par ses coefficients, ℝ[<i>x</i>] se traite comme des <i>n</i>-uplets de longueur variable.</p></div>',
   note:'« Point par point » remplace « coordonnée par coordonnée » : une fonction a une « coordonnée » f(x) pour chaque réel x, une infinité de coordonnées en quelque sorte.'},
  {h:'Additionner des fonctions, point par point',
   p:'<p>On prend <i>f</i>(<i>x</i>) = <i>x</i>² (bleu) et <i>g</i>(<i>x</i>) = <i>x</i> (jaune). La courbe épaisse est celle de <i>a</i>·<i>f</i> + <i>b</i>·<i>g</i>, c’est-à-dire de <i>x</i> ↦ <i>a</i><i>x</i>² + <i>b</i><i>x</i>. En chaque point, sa hauteur est <i>a</i> fois celle de <i>f</i> plus <i>b</i> fois celle de <i>g</i>. Règle <i>a</i> et <i>b</i>.</p><div class="idea"><p>Il n’y a pas de « parallélogramme » à dessiner pour des fonctions, mais la règle est la même qu’avec des couples : on ne combine jamais que des nombres, un point <i>x</i> à la fois. L’image à retenir : la courbe de <i>f</i> + <i>g</i> s’obtient en empilant, au-dessus de chaque abscisse, la hauteur de <i>g</i> sur celle de <i>f</i>.</p></div>',
   params:[{id:'a',l:'a',min:-2,max:2,step:.5,v:1},{id:'b',l:'b',min:-3,max:3,step:.5,v:-2}],
   draw:v=>fcomb(x=>x*x,x=>x,v.a,v.b,{x:[-3,3],y:[-5,7]}).svg(),
   info:v=>`<i>a</i><i>f</i> + <i>b</i><i>g</i> : <i>x</i> ↦ ${fmt(v.a)}<i>x</i>² ${v.b<0?'−':'+'} ${fmt(Math.abs(v.b))}<i>x</i>. En <i>x</i> = 1 : ${fmt(v.a)} · 1 + ${fmt(v.b)} · 1 = <b>${fmt(v.a+v.b)}</b> ; en <i>x</i> = 2 : ${fmt(v.a)} · 4 + ${fmt(v.b)} · 2 = <b>${fmt(4*v.a+2*v.b)}</b>.`,
   note:'Avec a = b = 0, on obtient la fonction nulle, le vecteur nul de F(ℝ, ℝ). Les combinaisons af + bg sont ici exactement les polynômes ax² + bx : un petit espace de fonctions à l’intérieur du grand.'},
  {h:'Calcul dans ℝ[x]',p:'Soit <i>P</i> = 2<i>x</i>² − <i>x</i> + 3 et <i>Q</i> = <i>x</i>² + 4<i>x</i> − 1. Quel est le coefficient de <i>x</i> dans 2<i>P</i> − 3<i>Q</i>&nbsp;?',lab:'coefficient de x =',ans:-14,
   why:'2P = 4x² − 2x + 6 et 3Q = 3x² + 12x − 3. Coefficient de x : −2 − 12 = −14. (Le résultat complet est x² − 14x + 9.)'},
  {h:'Les solutions d’une équation linéaire homogène',
   p:'<p>Revenons à la troisième situation du début : l’ensemble <i>S</i> des (<i>x</i> ; <i>y</i> ; <i>z</i>) ∈ ℝ³ tels que <i>x</i> + 2<i>y</i> − <i>z</i> = 0. Est-ce un espace vectoriel, avec les opérations de ℝ³ ?</p><div class="prop"><p>L’ensemble des solutions d’une équation linéaire <b>homogène</b> (second membre nul) <i>a</i><i>x</i> + <i>b</i><i>y</i> + <i>c</i><i>z</i> = 0 est un espace vectoriel pour les lois de ℝ³.</p></div><div class="why"><p>Deux choses à vérifier : que les lois de ℝ³ ne font pas sortir de <i>S</i>, et que les axiomes tiennent. Stabilité : si <b>u</b> = (<i>x</i> ; <i>y</i> ; <i>z</i>) et <b>u</b>′ = (<i>x</i>′ ; <i>y</i>′ ; <i>z</i>′) sont solutions, alors (<i>x</i> + <i>x</i>′) + 2(<i>y</i> + <i>y</i>′) − (<i>z</i> + <i>z</i>′) = (<i>x</i> + 2<i>y</i> − <i>z</i>) + (<i>x</i>′ + 2<i>y</i>′ − <i>z</i>′) = 0, donc <b>u</b> + <b>u</b>′ ∈ <i>S</i> ; et λ<i>x</i> + 2λ<i>y</i> − λ<i>z</i> = λ · 0 = 0, donc λ<b>u</b> ∈ <i>S</i>. Le vecteur nul est solution, l’opposé d’une solution aussi (prends λ = −1). Les axiomes de calcul, eux, sont vrais dans tout ℝ³, donc en particulier pour les éléments de <i>S</i> : rien à refaire.</p></div><div class="ex"><p>(1 ; 0 ; 1) et (0 ; 1 ; 2) sont solutions. Leur somme (1 ; 1 ; 3) aussi : 1 + 2 − 3 = 0. Et 5(1 ; 0 ; 1) = (5 ; 0 ; 5) : 5 − 5 = 0.</p></div><div class="warn"><p>Avec un second membre non nul, <i>x</i> + 2<i>y</i> − <i>z</i> = 4, ça casse : la somme de deux solutions donne 8, et (0 ; 0 ; 0) n’est pas solution. Le mot <b>homogène</b> est essentiel.</p></div>'},
  {kind:'Méthode',h:'Vérifier qu’un ensemble est un espace vectoriel',
   p:'<b>Quand :</b> on te donne un ensemble <i>E</i> avec une addition et une multiplication par les réels. <b>Deux cas.</b> <b>Cas 1, les lois sont celles d’un espace vectoriel connu</b> (ℝⁿ, fonctions, polynômes, matrices) et <i>E</i> en est une partie : les huit axiomes de calcul sont déjà vrais dans le grand espace, il suffit de vérifier que <i>E</i> n’est pas vide (en général, <b>0</b> ∈ <i>E</i>) et que <i>E</i> est <b>stable</b> : <b>u</b> + <b>v</b> ∈ <i>E</i> et λ<b>u</b> ∈ <i>E</i> pour tous <b>u</b>, <b>v</b> ∈ <i>E</i>, λ ∈ ℝ. <b>Cas 2, les lois sont nouvelles</b> : on identifie d’abord le vecteur nul (résoudre <b>u</b> + <b>e</b> = <b>u</b>) et les opposés, puis on vérifie les huit axiomes un à un avec des lettres. <b>Pour réfuter :</b> un seul contre-exemple numérique suffit, le plus souvent <b>0</b> ∉ <i>E</i>, ou une somme qui sort de <i>E</i>, ou un multiple négatif qui sort.',
   demo:{enonce:'<i>A</i> = {polynômes <i>P</i> de degré ≤ 2 tels que <i>P</i>(1) = 0} et <i>B</i> = {(<i>x</i> ; <i>y</i>) ∈ ℝ² : <i>xy</i> ≥ 0}, avec les lois usuelles. Espaces vectoriels&nbsp;?',
    etapes:[{f:'<i>A</i> : le polynôme nul est de degré ≤ 2 et vaut 0 en 1, donc <b>0</b> ∈ <i>A</i>.',w:'Cas 1 : les lois sont celles de ℝ[x]. On commence par le vecteur nul.'},
     {f:'Si <i>P</i>(1) = <i>Q</i>(1) = 0, alors (<i>P</i> + <i>Q</i>)(1) = 0 + 0 = 0 et (λ<i>P</i>)(1) = λ · 0 = 0 ; les degrés restent ≤ 2.',w:'Stabilité par les deux lois, avec des lettres.'},
     {f:'Donc <i>A</i> est un espace vectoriel : les axiomes de calcul sont hérités de ℝ[<i>x</i>].',w:'Rien d’autre à vérifier dans le cas 1.'},
     {f:'<i>B</i> : (0 ; 0) ∈ <i>B</i>, et λ(<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; λ<i>y</i>) a pour produit λ²<i>xy</i> ≥ 0 : stable par les scalaires.',w:'Jusqu’ici tout va bien, il reste l’addition.'},
     {f:'(1 ; 0) ∈ <i>B</i> et (0 ; −1) ∈ <i>B</i>, mais (1 ; 0) + (0 ; −1) = (1 ; −1) a pour produit −1 &lt; 0.',w:'Un contre-exemple numérique : la somme sort de B.'}],
    conclusion:'<i>A</i> est un espace vectoriel. <i>B</i> n’en est pas un : il n’est pas stable par addition. Géométriquement, <i>B</i> est la réunion de deux quarts de plan opposés, et la somme d’un vecteur de chaque morceau peut tomber ailleurs.'}},
  {h:'Contre-exemples : quel axiome tombe ?',
   p:'<p>Pour comprendre une définition, rien ne vaut des ensembles qui la ratent de justesse. À chaque fois, on cherche l’axiome précis qui échoue.</p><div class="ex"><p><b>ℝ² avec une loi externe modifiée.</b> Addition usuelle, mais λ ⊙ (<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; <i>y</i>) : on n’étire que la première coordonnée. (EV1), (EV3) et (EV4) tiennent (vérifie : 1 ⊙ (<i>x</i> ; <i>y</i>) = (<i>x</i> ; <i>y</i>)). Mais (2 + 3) ⊙ (1 ; 1) = (5 ; 1), alors que 2 ⊙ (1 ; 1) + 3 ⊙ (1 ; 1) = (2 ; 1) + (3 ; 1) = (5 ; 2). <b>(EV2) tombe.</b> D’ailleurs 0 ⊙ (1 ; 1) = (0 ; 1) ≠ <b>0</b>, ce qui contredit une conséquence des axiomes.</p></div><div class="ex"><p><b>[0 ; +∞[ avec les lois de ℝ.</b> Le réel 1 n’a pas d’opposé dans [0 ; +∞[ : <b>(G) tombe</b>. De plus (−1) · 1 = −1 sort de l’ensemble : la loi externe n’est même pas définie.</p></div><div class="ex"><p><b>ℤ² avec les lois de ℝ².</b> 0,5 · (1 ; 0) = (0,5 ; 0) ∉ ℤ² : la <b>loi externe n’est pas à valeurs dans l’ensemble</b>. ℤ² est un groupe abélien parfait, mais pas un espace vectoriel réel.</p></div><div class="ex"><p><b>ℝ² avec λ ⊙ (<i>x</i> ; <i>y</i>) = (λ<i>y</i> ; λ<i>x</i>).</b> 1 ⊙ (1 ; 2) = (2 ; 1) ≠ (1 ; 2) : <b>(EV4) tombe</b>. Et (EV3) aussi : (λμ) ⊙ <b>u</b> échange les coordonnées une fois, λ ⊙ (μ ⊙ <b>u</b>) deux fois.</p></div><div class="idea"><p>Trois façons de rater : une loi qui sort de l’ensemble, un groupe incomplet (pas d’opposé, pas de neutre), ou une loi externe qui ne respecte pas l’un des quatre axiomes de compatibilité.</p></div>'},
  {h:'Quel axiome échoue ?',p:'Sur ℝ², on garde l’addition usuelle et on pose λ ⊙ (<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; 0). Quel est le premier axiome parmi (EV1) à (EV4) qui échoue&nbsp;?',
   opts:['(EV1)','(EV2)','(EV3)','(EV4)'],ans:3,
   why:'(EV1) : λ ⊙ (u + v) = (λ(x + x′) ; 0) = λ ⊙ u + λ ⊙ v. (EV2) : ((λ + μ)x ; 0) = (λx ; 0) + (μx ; 0). (EV3) : ((λμ)x ; 0) des deux côtés. Mais 1 ⊙ (1 ; 2) = (1 ; 0) ≠ (1 ; 2) : (EV4) échoue.'},
  {h:'Une distributivité qui casse',p:'Avec λ ⊙ (<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; <i>y</i>) sur ℝ² (addition usuelle), quelle est la deuxième coordonnée de 2 ⊙ (3 ; 4) + 5 ⊙ (3 ; 4)&nbsp;?',lab:'deuxième coordonnée =',ans:8,
   why:'2 ⊙ (3 ; 4) = (6 ; 4) et 5 ⊙ (3 ; 4) = (15 ; 4) : la somme est (21 ; 8). Or (2 + 5) ⊙ (3 ; 4) = (21 ; 4). Les deux diffèrent : (EV2) échoue.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:'<div class="keep"><ul><li>Un espace vectoriel réel est un ensemble <i>E</i> avec une loi interne + et une loi externe ℝ × <i>E</i> → <i>E</i> tels que (<i>E</i>, +) est un groupe abélien et : λ(<b>u</b> + <b>v</b>) = λ<b>u</b> + λ<b>v</b> ; (λ + μ)<b>u</b> = λ<b>u</b> + μ<b>u</b> ; (λμ)<b>u</b> = λ(μ<b>u</b>) ; 1<b>u</b> = <b>u</b>.</li><li>Sans (EV4), la loi « λ·<b>u</b> = <b>0</b> » passerait le test : chaque axiome a un rôle.</li><li>Conséquences démontrées : 0·<b>v</b> = <b>0</b>, λ·<b>0</b> = <b>0</b>, (−1)·<b>v</b> = −<b>v</b>, et λ<b>v</b> = <b>0</b> ⇒ λ = 0 ou <b>v</b> = <b>0</b>. Preuves : écrire 0 = 0 + 0 et distribuer, puis simplifier dans le groupe ; multiplier par 1/λ.</li><li>Exemples : ℝⁿ, M₂(ℝ), ℝ[<i>x</i>], ℝ[<i>x</i>]≤ₙ, F(ℝ, ℝ), les suites, les solutions d’une équation linéaire homogène. Les axiomes se vérifient coordonnée par coordonnée ou point par point.</li><li>Méthode : si les lois sont celles d’un espace connu, il suffit de vérifier <b>0</b> ∈ <i>E</i> et la stabilité par + et par λ. Pour réfuter : un contre-exemple numérique.</li><li>Contre-exemples : [0 ; +∞[ (pas d’opposés), ℤ² (la loi externe sort), λ ⊙ (<i>x</i> ; <i>y</i>) = (λ<i>x</i> ; <i>y</i>) (EV2 tombe), (λ<i>y</i> ; λ<i>x</i>) (EV4 tombe).</li></ul></div>'},
  {kind:'Problème',h:'Un espace de fonctions : a·cos + b·sin',
   p:'On note <i>E</i> l’ensemble des fonctions de la forme <i>f</i>(<i>x</i>) = <i>a</i> cos <i>x</i> + <i>b</i> sin <i>x</i>, avec <i>a</i>, <i>b</i> ∈ ℝ, muni des lois de F(ℝ, ℝ). On veut vérifier que c’est un espace vectoriel, calculer dedans, et découvrir que certaines fonctions qui n’ont pas l’air d’y être y sont quand même.',
   fig:(()=>{ const P=plane({x:[-3.5,3.5],y:[-2,2],lab:1}); P.fn(Math.cos,{c:'var(--math)',w:2,op:.6}).fn(Math.sin,{c:'var(--spark)',w:2,op:.6}).fn(x=>Math.sin(x+Math.PI/4),{c:'var(--accent)',w:4}); P.text(-3.3,1.6,'sin(x + π/4)',{c:'var(--accent)',s:12}); return P.svg(); })(),
   parts:[
    {q:'a) Quel est le vecteur nul de <i>E</i>&nbsp;?',opts:['La fonction cos','La fonction nulle, obtenue pour <i>a</i> = <i>b</i> = 0','Le nombre 0','La fonction <i>x</i> ↦ cos <i>x</i> + sin <i>x</i>'],ans:1,hint:'Le vecteur nul de F(ℝ, ℝ) est la fonction qui vaut 0 partout. Est-elle de la forme a cos + b sin ?',why:'0 · cos x + 0 · sin x = 0 pour tout x : la fonction nulle appartient à E, et c’est le neutre de l’addition des fonctions.'},
    {q:'b) Soit <i>f</i> = 2 cos + sin et <i>g</i> = cos − 3 sin. Quel est le coefficient de sin dans 3<i>f</i> − <i>g</i>&nbsp;?',lab:'coefficient de sin =',ans:6,hint:'Calcule point par point : 3f(x) − g(x), puis regroupe les cos et les sin.',why:'3f − g = (6 cos + 3 sin) − (cos − 3 sin) = 5 cos + 6 sin. Le coefficient de sin est 3 + 3 = 6.'},
    {q:'c) Pourquoi <i>E</i> est-il stable par addition&nbsp;?',opts:['Parce que cos et sin sont continues','Parce que (<i>a</i> cos + <i>b</i> sin) + (<i>a</i>′ cos + <i>b</i>′ sin) = (<i>a</i> + <i>a</i>′) cos + (<i>b</i> + <i>b</i>′) sin, qui est encore de la forme voulue','Parce que la somme de deux fonctions est une fonction','Parce que cos² + sin² = 1'],ans:1,
     hint:'Écris la somme de deux éléments de E et regroupe.',why:'La somme est de la même forme, avec les coefficients a + a′ et b + b′. De même λ(a cos + b sin) = (λa) cos + (λb) sin. Avec le vecteur nul, c’est le cas 1 de la méthode : E est un espace vectoriel.'},
    {q:'d) La fonction <i>h</i>(<i>x</i>) = sin(<i>x</i> + π/4) appartient à <i>E</i>. Quel est son coefficient <i>a</i> devant cos&nbsp;? (Arrondis au centième.)',lab:'a =',ans:0.7071,tol:0.006,hint:'Développe sin(x + π/4) = sin x cos(π/4) + cos x sin(π/4).',why:'sin(x + π/4) = (√2/2) sin x + (√2/2) cos x. Donc a = b = √2/2 ≈ 0,71.'},
    {q:'e) La dérivée de <i>f</i> = <i>a</i> cos + <i>b</i> sin est <i>f</i>′ = −<i>a</i> sin + <i>b</i> cos, encore dans <i>E</i>. Quel est le coefficient de cos dans la dérivée de 2 cos + 5 sin&nbsp;?',lab:'coefficient de cos =',ans:5,hint:'(cos)′ = −sin et (sin)′ = cos.',why:'(2 cos + 5 sin)′ = −2 sin + 5 cos : le coefficient de cos est 5. Dériver envoie E dans E.'},
   ],
   sol:'<i>E</i> est une partie de F(ℝ, ℝ) qui contient la fonction nulle (<i>a</i> = <i>b</i> = 0) et qui est stable : (<i>a</i> cos + <i>b</i> sin) + (<i>a</i>′ cos + <i>b</i>′ sin) = (<i>a</i> + <i>a</i>′) cos + (<i>b</i> + <i>b</i>′) sin et λ(<i>a</i> cos + <i>b</i> sin) = (λ<i>a</i>) cos + (λ<i>b</i>) sin. Les axiomes de calcul sont hérités de F(ℝ, ℝ) : <i>E</i> est un espace vectoriel.<br>Calcul : 3<i>f</i> − <i>g</i> = 5 cos + 6 sin.<br>La formule d’addition donne sin(<i>x</i> + π/4) = (√2/2) cos <i>x</i> + (√2/2) sin <i>x</i> : cette fonction est dans <i>E</i>, avec <i>a</i> = <i>b</i> = √2/2 ≈ 0,71. Plus généralement, toute fonction <i>x</i> ↦ <i>R</i> sin(<i>x</i> + φ) est dans <i>E</i>.<br>Enfin (<i>a</i> cos + <i>b</i> sin)′ = <i>b</i> cos − <i>a</i> sin ∈ <i>E</i> : la dérivation ne fait pas sortir de <i>E</i>. Pour 2 cos + 5 sin, la dérivée est 5 cos − 2 sin.'},
  {kind:'Problème',h:'Une addition qui multiplie',
   p:'Sur <i>E</i> = ]0 ; +∞[, on définit deux lois inhabituelles : <i>x</i> ⊕ <i>y</i> = <i>xy</i> (l’« addition » des vecteurs est le produit des réels) et λ ⊙ <i>x</i> = <i>x</i><sup>λ</sup> (la « multiplication par un scalaire » est une puissance). On va voir que (<i>E</i>, ⊕, ⊙) est un espace vectoriel réel, en identifiant son vecteur nul et ses opposés, puis en traduisant chaque axiome en une règle connue sur les puissances.',
   parts:[
    {q:'a) Que vaut 3 ⊕ 4&nbsp;?',lab:'3 ⊕ 4 =',ans:12,hint:'Applique la définition de ⊕.',why:'3 ⊕ 4 = 3 · 4 = 12. La loi est interne : le produit de deux réels strictement positifs est strictement positif.'},
    {q:'b) Quel est le vecteur nul de <i>E</i>, c’est-à-dire l’élément <i>e</i> tel que <i>x</i> ⊕ <i>e</i> = <i>x</i> pour tout <i>x</i>&nbsp;?',lab:'e =',ans:1,hint:'Résous x · e = x.',why:'x · e = x pour tout x &gt; 0 impose e = 1. Le « zéro » de cet espace est le nombre 1.'},
    {q:'c) Quel est l’opposé de 4 dans <i>E</i>, c’est-à-dire l’élément <i>y</i> tel que 4 ⊕ <i>y</i> = 1&nbsp;?',lab:'y =',ans:0.25,tol:0.001,hint:'Résous 4 · y = 1.',why:'y = 1/4 = 0,25. L’opposé de x est 1/x, qui est bien dans ]0 ; +∞[. Vérifie aussi : (−1) ⊙ 4 = 4⁻¹ = 0,25, conforme à la règle (−1)·v = −v.'},
    {q:'d) Calcule (3 ⊙ 2) ⊕ ((−1) ⊙ 4).',lab:'résultat =',ans:2,hint:'3 ⊙ 2 = 2³, (−1) ⊙ 4 = 4⁻¹, puis ⊕ multiplie.',why:'2³ · 4⁻¹ = 8 · 0,25 = 2.'},
    {q:'e) L’axiome (EV2), (λ + μ) ⊙ <i>x</i> = (λ ⊙ <i>x</i>) ⊕ (μ ⊙ <i>x</i>), se traduit par quelle règle sur les puissances&nbsp;?',opts:['<i>x</i><sup>λμ</sup> = (<i>x</i><sup>λ</sup>)<sup>μ</sup>','(<i>xy</i>)<sup>λ</sup> = <i>x</i><sup>λ</sup><i>y</i><sup>λ</sup>','<i>x</i><sup>λ + μ</sup> = <i>x</i><sup>λ</sup> · <i>x</i><sup>μ</sup>','<i>x</i>¹ = <i>x</i>'],ans:2,
     hint:'Remplace ⊙ par une puissance et ⊕ par un produit dans l’égalité.',why:'(λ + μ) ⊙ x = x^(λ+μ) et (λ ⊙ x) ⊕ (μ ⊙ x) = x^λ · x^μ. L’axiome est la règle x^(λ+μ) = x^λ x^μ. Les trois autres règles traduisent (EV1), (EV3) et (EV4).'},
   ],
   sol:'(<i>E</i>, ⊕) est le groupe abélien (]0 ; +∞[, ·) : produit associatif et commutatif, neutre 1, symétrique 1/<i>x</i>. La loi ⊙ est bien à valeurs dans <i>E</i> : <i>x</i><sup>λ</sup> &gt; 0.<br>Les quatre axiomes sont des règles sur les puissances : (EV1) λ ⊙ (<i>x</i> ⊕ <i>y</i>) = (<i>xy</i>)<sup>λ</sup> = <i>x</i><sup>λ</sup><i>y</i><sup>λ</sup> = (λ ⊙ <i>x</i>) ⊕ (λ ⊙ <i>y</i>) ; (EV2) <i>x</i><sup>λ + μ</sup> = <i>x</i><sup>λ</sup><i>x</i><sup>μ</sup> ; (EV3) <i>x</i><sup>λμ</sup> = (<i>x</i><sup>μ</sup>)<sup>λ</sup> ; (EV4) <i>x</i>¹ = <i>x</i>. Donc <i>E</i> est un espace vectoriel réel.<br>Vecteur nul : 1. Opposé de 4 : 1/4. Et (3 ⊙ 2) ⊕ ((−1) ⊙ 4) = 8 · 1/4 = 2.<br>Le dictionnaire est le logarithme : ln(<i>x</i> ⊕ <i>y</i>) = ln <i>x</i> + ln <i>y</i> et ln(λ ⊙ <i>x</i>) = λ ln <i>x</i>. Vu à travers ln, <i>E</i> est une copie exacte de ℝ avec ses lois usuelles.'},
]},
);

COURS.push(
/* ===================== 3. SOUS-ESPACES VECTORIELS ===================== */
{subj:'gred',sem:'lin',id:'gred-sous-espaces',h:'Sous-espaces vectoriels',p:'Les espaces vectoriels contenus dans un espace vectoriel : le critère de stabilité, les contre-exemples du plan, intersection et somme, le sous-espace engendré Vect, somme directe et supplémentaires.',steps:[
  {h:'Des espaces dans l’espace',
   p:'<p>Dans le plan, une droite vectorielle ℝ<b>u</b> est stable par + et par les scalaires : c’est un espace vectoriel à l’intérieur de ℝ², avec les mêmes lois. De même, les polynômes de degré ≤ 2 à l’intérieur de ℝ[<i>x</i>], les solutions de <i>x</i> + 2<i>y</i> − <i>z</i> = 0 à l’intérieur de ℝ³, les fonctions <i>a</i> cos + <i>b</i> sin à l’intérieur de F(ℝ, ℝ). Ces « espaces dans l’espace » méritent un nom.</p><div class="def"><p>Soit <i>E</i> un espace vectoriel. Une partie <i>F</i> ⊂ <i>E</i> est un <b>sous-espace vectoriel</b> de <i>E</i> si <i>F</i>, munie des lois de <i>E</i> (restreintes à <i>F</i>), est elle-même un espace vectoriel.</p></div><div class="idea"><p>Un sous-espace n’invente rien : il réutilise l’addition et la loi externe de <i>E</i>. La seule question est de savoir si ces lois « restent dans <i>F</i> », et si <i>F</i> contient ce qu’il faut (le vecteur nul, les opposés). Les axiomes de calcul, eux, sont vrais pour tous les vecteurs de <i>E</i>, donc en particulier pour ceux de <i>F</i>.</p></div><div class="ex"><p>{<b>0</b>} et <i>E</i> lui-même sont toujours des sous-espaces de <i>E</i>, les deux extrêmes. Dans ℝ², toute droite vectorielle ℝ<b>u</b> est un sous-espace. On verra qu’il n’y en a pas d’autres : {<b>0</b>}, les droites vectorielles et ℝ² tout entier.</p></div>',
   note:'Attention au vocabulaire : « sous-espace » tout seul veut toujours dire « sous-espace vectoriel » dans ce cours. Une droite qui ne passe pas par l’origine n’en est pas un, on va le voir.'},
  {h:'Le critère pratique',
   p:'<p>Vérifier les huit axiomes pour chaque candidat serait long. Heureusement, trois contrôles suffisent.</p><div class="thm"><p>Une partie <i>F</i> d’un espace vectoriel <i>E</i> est un sous-espace vectoriel si et seulement si :<br>(1) <i>F</i> ≠ ∅ (en pratique, on vérifie <b>0</b> ∈ <i>F</i>) ;<br>(2) pour tous <b>u</b>, <b>v</b> ∈ <i>F</i> : <b>u</b> + <b>v</b> ∈ <i>F</i> ;<br>(3) pour tout <b>u</b> ∈ <i>F</i> et tout λ ∈ ℝ : λ<b>u</b> ∈ <i>F</i>.<br>Les conditions (2) et (3) se résument en une seule : pour tous <b>u</b>, <b>v</b> ∈ <i>F</i> et λ, μ ∈ ℝ, <b>λ<b>u</b> + μ<b>v</b> ∈ <i>F</i></b> (stabilité par combinaison linéaire).</p></div><div class="why"><p>Si <i>F</i> est un sous-espace, il est non vide (il a un vecteur nul) et stable par ses lois, qui sont celles de <i>E</i> : (1), (2), (3) tiennent. Réciproquement, supposons (1), (2), (3). Prenons <b>u</b> ∈ <i>F</i> (possible par (1)) : par (3), 0·<b>u</b> = <b>0</b> ∈ <i>F</i>, et (−1)·<b>u</b> = −<b>u</b> ∈ <i>F</i>. Ainsi (<i>F</i>, +) a un neutre et des opposés ; l’associativité et la commutativité sont vraies dans <i>E</i>, donc dans <i>F</i> : c’est un groupe abélien. Les axiomes (EV1) à (EV4) sont des égalités vraies pour tous les vecteurs de <i>E</i>, donc pour ceux de <i>F</i>. Enfin (2) et (3) garantissent que les lois restent à valeurs dans <i>F</i>.</p></div><div class="idea"><p>Le travail est tout entier dans la <b>stabilité</b>. Les propriétés des deux chapitres précédents (0·<b>u</b> = <b>0</b>, (−1)·<b>u</b> = −<b>u</b>) font le reste : c’est pour cela qu’on les a démontrées.</p></div>',
   note:'Pourquoi « non vide » plutôt que « contient 0 » dans l’énoncé ? Parce que c’est la condition minimale ; mais dès qu’il y a un vecteur, 0 suit. Et si 0 ∉ F, inutile d’aller plus loin : F n’est pas un sous-espace.'},
  {kind:'Méthode',h:'Montrer qu’une partie est un sous-espace, ou non',
   p:'<b>Quand :</b> on te donne une partie <i>F</i> d’un espace vectoriel connu, en général par une condition (une équation, une propriété). <b>Pour prouver :</b> 1) vérifie que <b>0</b> satisfait la condition ; 2) prends deux éléments <b>u</b>, <b>v</b> de <i>F</i> et deux réels λ, μ <b>quelconques</b> (avec des lettres), et montre que λ<b>u</b> + μ<b>v</b> satisfait la condition, en regroupant pour faire apparaître les conditions connues. <b>Pour réfuter :</b> un seul contre-exemple numérique : <b>0</b> ∉ <i>F</i>, ou deux éléments dont la somme sort, ou un élément dont un multiple (souvent négatif) sort. <b>Signaux d’alarme :</b> une constante non nulle dans l’équation, une inégalité, un produit ou un carré de l’inconnue, une « ou » dans la condition.',
   demo:{enonce:'Dans ℝ³, <i>F</i> = {(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>x</i> − 2<i>y</i> + <i>z</i> = 0}. Dans ℝ[<i>x</i>], <i>G</i> = {<i>P</i> : <i>P</i>(1) = 0} et <i>H</i> = {<i>P</i> : <i>P</i>(0) = 1}. Sous-espaces&nbsp;?',
    etapes:[{f:'<i>F</i> : 0 − 0 + 0 = 0, donc <b>0</b> ∈ <i>F</i>.',w:'Premier contrôle.'},
     {f:'Soit <b>u</b> = (<i>x</i> ; <i>y</i> ; <i>z</i>), <b>v</b> = (<i>x</i>′ ; <i>y</i>′ ; <i>z</i>′) dans <i>F</i>. Alors λ<b>u</b> + μ<b>v</b> = (λ<i>x</i> + μ<i>x</i>′ ; λ<i>y</i> + μ<i>y</i>′ ; λ<i>z</i> + μ<i>z</i>′) et (λ<i>x</i> + μ<i>x</i>′) − 2(λ<i>y</i> + μ<i>y</i>′) + (λ<i>z</i> + μ<i>z</i>′) = λ(<i>x</i> − 2<i>y</i> + <i>z</i>) + μ(<i>x</i>′ − 2<i>y</i>′ + <i>z</i>′) = 0.',w:'On regroupe par λ et par μ pour retrouver les deux équations connues.'},
     {f:'Donc <i>F</i> est un sous-espace de ℝ³ (c’est un plan passant par l’origine).',w:'Le critère est satisfait.'},
     {f:'<i>G</i> : le polynôme nul vaut 0 en 1. Si <i>P</i>(1) = <i>Q</i>(1) = 0, alors (λ<i>P</i> + μ<i>Q</i>)(1) = λ · 0 + μ · 0 = 0. <i>G</i> est un sous-espace.',w:'Même schéma, la condition est « valeur en un point ».'},
     {f:'<i>H</i> : le polynôme nul vaut 0 en 0, pas 1. Donc <b>0</b> ∉ <i>H</i>.',w:'Le contrôle le plus rapide suffit à réfuter. (La constante 1 était le signal.)'}],
    conclusion:'<i>F</i> et <i>G</i> sont des sous-espaces ; <i>H</i> n’en est pas un. Remarque la forme des preuves : toujours « regrouper par λ et μ pour retrouver la condition connue ».'}},
  {h:'Sous-espace ou pas ?',p:'Laquelle de ces parties de ℝ³ est un sous-espace vectoriel&nbsp;?',
   opts:['{(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>x</i> + <i>y</i> + <i>z</i> = 1}','{(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>z</i> = <i>x</i>²}','{(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>x</i> = <i>y</i> et <i>z</i> = 0}','{(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>x</i> ≥ 0}'],ans:2,
   why:'x = y et z = 0 : 0 convient, et si deux vecteurs ont x = y, z = 0, toute combinaison aussi. C’est la droite ℝ(1 ; 1 ; 0). Les autres : 0 ∉ (somme = 1) ; (1 ; 0 ; 1) vérifie z = x² mais 2(1 ; 0 ; 1) = (2 ; 0 ; 2) ne le vérifie pas ; (1 ; 0 ; 0) a x ≥ 0 mais pas son opposé.'},
  {h:'Les contre-exemples du plan',
   p:'<p>Dans ℝ², trois parties ressemblent à des sous-espaces sans en être. Chacune rate exactement une condition du critère.</p><div class="ex"><p><b>Une droite qui ne passe pas par l’origine</b>, par exemple <i>y</i> = <i>x</i> + 1 : (0 ; 0) n’y est pas, car 0 ≠ 1. Condition (1) ratée. D’ailleurs (0 ; 1) + (1 ; 2) = (1 ; 3) et 3 ≠ 2 : la somme sort aussi.</p></div><div class="ex"><p><b>Un demi-plan</b>, par exemple {(<i>x</i> ; <i>y</i>) : <i>y</i> ≥ 0} : il contient <b>0</b> et la somme de deux de ses vecteurs y reste (<i>y</i> + <i>y</i>′ ≥ 0). Mais (−1) · (0 ; 1) = (0 ; −1) en sort. Condition (3) ratée : les inégalités ne survivent pas aux scalaires négatifs.</p></div><div class="ex"><p><b>La réunion de deux droites vectorielles</b>, par exemple l’axe des <i>x</i> et la droite <i>y</i> = 2<i>x</i> : <b>0</b> y est, les multiples y restent (chaque droite est stable). Mais (1 ; 0) + (1 ; 2) = (2 ; 2) n’est sur aucune des deux. Condition (2) ratée. Règle les curseurs ci-dessous pour le voir.</p></div><div class="idea"><p>Ces trois échecs sont les trois seuls possibles, et ils guident la réfutation : pas de <b>0</b>, pas stable par un scalaire, pas stable par une somme.</p></div>',
   params:[{id:'s',l:'u = (s ; 0) sur l’axe',min:-3,max:3,v:2},{id:'t',l:'v = (t ; 2t) sur y = 2x',min:-2,max:2,v:1}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); ln(P,1,0,{c:'var(--ok)',w:2.5}); ln(P,1,2,{c:'var(--ok)',w:2.5}); const u=[v.s,0], w=[v.t,2*v.t], s=[u[0]+w[0],u[1]+w[1]];
     if(v.s||v.t) P.poly([[0,0],u,s,w],{fill:'var(--accent)',fo:.1,c:'var(--muted)',w:1.5,dash:true});
     if(v.s) P.arrow(0,0,u[0],u[1],{c:'var(--math)',w:3}); if(v.t) P.arrow(0,0,w[0],w[1],{c:'var(--spark)',w:3}); if(s[0]||s[1]) P.arrow(0,0,s[0],s[1],{c:(v.s&&v.t)?'var(--bad)':'var(--accent)',w:4}); P.dot(s[0],s[1],{r:5,c:(v.s&&v.t)?'var(--bad)':'var(--accent)',l:'u + v',dx:8,dy:-8}); return P.svg(); },
   info:v=>{ const s=[v.s+v.t,2*v.t]; const on=(s[1]===0)||(s[1]===2*s[0]); return `<b>u</b> + <b>v</b> = ${V2(s[0],s[1])} : ${on?'encore dans la réunion (un des deux vecteurs est nul).':'<b>sur aucune des deux droites</b>. La réunion n’est pas stable par addition.'}`; }},
  {kind:'Pratique',h:'Fais sortir la somme',p:'Les deux droites vertes sont <i>D</i>₁ : <i>y</i> = 0 et <i>D</i>₂ : <i>y</i> = 2<i>x</i>. Choisis <b>u</b> ∈ <i>D</i>₁ et <b>v</b> ∈ <i>D</i>₂ de sorte que <b>u</b> + <b>v</b> ne soit dans aucune des deux droites.',
   params:[{id:'s',l:'u = (s ; 0)',min:-3,max:3,v:0},{id:'t',l:'v = (t ; 2t)',min:-2,max:2,v:1}],
   draw:v=>{ const P=plane({x:[-6,6],y:[-6,6],lab:2}); ln(P,1,0,{c:'var(--ok)',w:2.5}); ln(P,1,2,{c:'var(--ok)',w:2.5}); const u=[v.s,0], w=[v.t,2*v.t], s=[u[0]+w[0],u[1]+w[1]];
     if(v.s) P.arrow(0,0,u[0],u[1],{c:'var(--math)',w:3}); if(v.t) P.arrow(0,0,w[0],w[1],{c:'var(--spark)',w:3}); if(s[0]||s[1]) P.arrow(0,0,s[0],s[1],{c:'var(--accent)',w:4}); P.dot(s[0],s[1],{r:5,c:'var(--accent)',l:'u + v',dx:8,dy:-8}); return P.svg(); },
   info:v=>`<b>u</b> + <b>v</b> = ${V2(v.s+v.t,2*v.t)}`,
   ok:v=>v.s!==0&&v.t!==0,
   why:'Dès que u ≠ 0 et v ≠ 0, la somme (s + t ; 2t) a y = 2t ≠ 0 (pas sur D₁) et y ≠ 2x car 2t ≠ 2(s + t) (pas sur D₂). Un seul exemple suffit à prouver que D₁ ∪ D₂ n’est pas un sous-espace.'},
  {h:'L’intersection de deux sous-espaces',
   p:'<p>La réunion de deux sous-espaces n’en est pas un, en général. L’intersection, si.</p><div class="prop"><p>Si <i>F</i> et <i>G</i> sont deux sous-espaces vectoriels de <i>E</i>, alors <b><i>F</i> ∩ <i>G</i></b> est un sous-espace vectoriel de <i>E</i>. (Et de même pour une intersection de plusieurs sous-espaces, même une infinité.)</p></div><div class="why"><p>On applique le critère. <b>0</b> ∈ <i>F</i> et <b>0</b> ∈ <i>G</i>, donc <b>0</b> ∈ <i>F</i> ∩ <i>G</i>. Soit <b>u</b>, <b>v</b> ∈ <i>F</i> ∩ <i>G</i> et λ, μ ∈ ℝ. Comme <b>u</b>, <b>v</b> ∈ <i>F</i> et que <i>F</i> est un sous-espace, λ<b>u</b> + μ<b>v</b> ∈ <i>F</i>. Même raisonnement dans <i>G</i> : λ<b>u</b> + μ<b>v</b> ∈ <i>G</i>. Donc λ<b>u</b> + μ<b>v</b> ∈ <i>F</i> ∩ <i>G</i>.</p></div><div class="idea"><p>Appartenir à l’intersection, c’est satisfaire <b>les deux</b> conditions à la fois ; chacune est préservée par les combinaisons, donc les deux ensemble aussi. Pour la réunion, il suffit de satisfaire <b>l’une ou l’autre</b>, et la somme d’un vecteur de chaque côté peut n’en satisfaire aucune.</p></div><div class="ex"><p>Dans ℝ³, <i>F</i> : <i>x</i> + <i>y</i> + <i>z</i> = 0 et <i>G</i> : <i>x</i> − <i>y</i> = 0 sont deux plans. Leur intersection est l’ensemble des vecteurs qui vérifient les deux équations : <i>x</i> = <i>y</i> et <i>z</i> = −2<i>x</i>, c’est-à-dire la droite ℝ(1 ; 1 ; −2). Les solutions d’un <b>système</b> d’équations homogènes forment toujours un sous-espace : c’est une intersection de sous-espaces.</p></div>',
   note:'Deux plans vectoriels de ℝ³ se coupent toujours au moins selon une droite : ils passent tous deux par l’origine, et ils ne peuvent pas être « parallèles sans se toucher ».'},
  {h:'Une droite dans deux plans',p:'Dans ℝ³, soit <i>F</i> : <i>x</i> + <i>y</i> + <i>z</i> = 0 et <i>G</i> : <i>x</i> − <i>y</i> = 0. Le vecteur de <i>F</i> ∩ <i>G</i> dont la première coordonnée vaut 1 a pour troisième coordonnée <i>z</i> = ?',lab:'z =',ans:-2,
   why:'x − y = 0 donne y = 1, puis 1 + 1 + z = 0 donne z = −2. F ∩ G = ℝ(1 ; 1 ; −2).'},
  {h:'La somme de deux sous-espaces',
   p:'<p>Puisque la réunion <i>F</i> ∪ <i>G</i> n’est pas un sous-espace, quel est le plus petit sous-espace qui contient <i>F</i> et <i>G</i> ? Il doit contenir toutes les sommes <b>f</b> + <b>g</b>. Ça suffit.</p><div class="def"><p>La <b>somme</b> de deux sous-espaces <i>F</i> et <i>G</i> de <i>E</i> est <b><i>F</i> + <i>G</i> = {<b>f</b> + <b>g</b> : <b>f</b> ∈ <i>F</i>, <b>g</b> ∈ <i>G</i>}</b>.</p></div><div class="prop"><p><i>F</i> + <i>G</i> est un sous-espace vectoriel de <i>E</i>. Il contient <i>F</i> et <i>G</i>, et tout sous-espace qui contient <i>F</i> et <i>G</i> contient <i>F</i> + <i>G</i> : c’est le <b>plus petit</b> sous-espace contenant <i>F</i> ∪ <i>G</i>.</p></div><div class="why"><p>Critère : <b>0</b> = <b>0</b> + <b>0</b> ∈ <i>F</i> + <i>G</i>. Si <b>u</b> = <b>f</b> + <b>g</b> et <b>u</b>′ = <b>f</b>′ + <b>g</b>′, alors λ<b>u</b> + μ<b>u</b>′ = (λ<b>f</b> + μ<b>f</b>′) + (λ<b>g</b> + μ<b>g</b>′), somme d’un vecteur de <i>F</i> et d’un vecteur de <i>G</i>. Il contient <i>F</i> (prends <b>g</b> = <b>0</b>) et <i>G</i>. Enfin, si un sous-espace <i>H</i> contient <i>F</i> et <i>G</i>, il contient chaque <b>f</b> et chaque <b>g</b>, donc chaque <b>f</b> + <b>g</b> par stabilité.</p></div><div class="ex"><p>Dans ℝ², <i>D</i>₁ = ℝ(1 ; 0) et <i>D</i>₂ = ℝ(1 ; 2). Leur somme contient (<i>s</i> ; 0) + (<i>t</i> ; 2<i>t</i>) = (<i>s</i> + <i>t</i> ; 2<i>t</i>) : pour atteindre (<i>x</i> ; <i>y</i>), on prend <i>t</i> = <i>y</i>/2 et <i>s</i> = <i>x</i> − <i>y</i>/2. Donc <i>D</i>₁ + <i>D</i>₂ = ℝ². Les deux droites vertes de la figure plus haut engendrent tout le plan.</p></div>'},
  {h:'Le sous-espace engendré : Vect',
   p:'<p>On part de quelques vecteurs <b>v</b>₁, …, <b>v</b>ₖ de <i>E</i>. Quel est le plus petit sous-espace qui les contient ? Il doit contenir toutes leurs combinaisons linéaires. Et là encore, ça suffit.</p><div class="def"><p>Le <b>sous-espace engendré</b> par <b>v</b>₁, …, <b>v</b>ₖ est l’ensemble de leurs combinaisons linéaires :<br><b>Vect(<b>v</b>₁, …, <b>v</b>ₖ) = {λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ : λ₁, …, λₖ ∈ ℝ}</b>.<br>On dit que la famille (<b>v</b>₁, …, <b>v</b>ₖ) <b>engendre</b> ce sous-espace.</p></div><div class="prop"><p>Vect(<b>v</b>₁, …, <b>v</b>ₖ) est un sous-espace vectoriel qui contient chaque <b>v</b>ᵢ, et c’est le plus petit : tout sous-espace contenant <b>v</b>₁, …, <b>v</b>ₖ contient Vect(<b>v</b>₁, …, <b>v</b>ₖ).</p></div><div class="why"><p>Il contient <b>0</b> (tous les λᵢ nuls) et <b>v</b>ᵢ (λᵢ = 1, les autres nuls). La combinaison λ(Σλᵢ<b>v</b>ᵢ) + μ(Σμᵢ<b>v</b>ᵢ) = Σ(λλᵢ + μμᵢ)<b>v</b>ᵢ est encore une combinaison des <b>v</b>ᵢ : stabilité. Et un sous-espace <i>H</i> qui contient les <b>v</b>ᵢ contient λᵢ<b>v</b>ᵢ, puis leurs sommes, par stabilité : il contient tout Vect.</p></div><div class="ex"><p>Vect(<b>u</b>) = ℝ<b>u</b>, la droite vectorielle. Dans ℝ², Vect((1 ; 0), (0 ; 1)) = ℝ², car (<i>x</i> ; <i>y</i>) = <i>x</i>(1 ; 0) + <i>y</i>(0 ; 1). Dans ℝ[<i>x</i>], Vect(1, <i>x</i>, <i>x</i>²) = ℝ[<i>x</i>]≤₂. Et Vect(<b>u</b>, <b>v</b>) = ℝ<b>u</b> + ℝ<b>v</b> : la somme de deux droites.</p></div>',
   note:'Si v et u sont colinéaires, Vect(u, v) = Vect(u) : ajouter un vecteur déjà dans le sous-espace n’agrandit rien. Vect(u, v) est un plan exactement quand u et v ne sont pas colinéaires.'},
  {h:'Un plan vectoriel dans l’espace',
   p:'<p>Dans ℝ³, on prend <b>u</b> = (2 ; 0 ; 1) et <b>v</b> = (0 ; 2 ; 1). Le sous-espace Vect(<b>u</b>, <b>v</b>) est le <b>plan</b> qui passe par l’origine et contient les deux flèches : la nappe grise. Chaque point du plan est atteint par une combinaison <i>a</i><b>u</b> + <i>b</i><b>v</b>, et le quadrillage de la nappe est tracé par les vecteurs <i>a</i><b>u</b> + <i>b</i><b>v</b> à coefficients entiers ou demi-entiers. Règle <i>a</i> et <i>b</i>.</p>',
   params:[{id:'a',l:'a',min:-1.5,max:1.5,step:.5,v:1},{id:'b',l:'b',min:-1.5,max:1.5,step:.5,v:-0.5}],
   draw:v=>plan3([2,0,1],[0,2,1],v.a,v.b),
   info:v=>`${fmt(v.a)} · (2 ; 0 ; 1) + ${fmt(v.b)} · (0 ; 2 ; 1) = <b>${V3(2*v.a,2*v.b,v.a+v.b)}</b>. Ses coordonnées vérifient <i>x</i> + <i>y</i> − 2<i>z</i> = ${fmt(2*v.a+2*v.b-2*(v.a+v.b))} : c’est l’équation du plan.`,
   note:'Un plan vectoriel de ℝ³ se décrit de deux façons : par deux vecteurs qui l’engendrent (Vect(u, v)) ou par une équation homogène (x + y − 2z = 0). La méthode suivante permet de passer de l’une à l’autre, en testant l’appartenance.'},
  {kind:'Méthode',h:'Décider si un vecteur appartient à Vect(u, v)',
   p:'<b>Quand :</b> on demande si <b>w</b> ∈ Vect(<b>u</b>, <b>v</b>), ou si Vect(<b>u</b>, <b>v</b>) contient un certain vecteur. <b>Pourquoi :</b> par définition, <b>w</b> ∈ Vect(<b>u</b>, <b>v</b>) si et seulement si l’équation <i>a</i><b>u</b> + <i>b</i><b>v</b> = <b>w</b> a une solution (<i>a</i> ; <i>b</i>). <b>Comment :</b> 1) écris cette égalité coordonnée par coordonnée : dans ℝ³, trois équations pour deux inconnues ; 2) résous avec deux équations ; 3) <b>reporte dans la troisième</b> : si elle est vérifiée, <b>w</b> ∈ Vect(<b>u</b>, <b>v</b>) et tu as ses coefficients ; sinon <b>w</b> ∉ Vect(<b>u</b>, <b>v</b>). Même démarche pour des polynômes (égalité des coefficients) ou des matrices (égalité des cases).',
   demo:{enonce:'Soit <b>u</b> = (1 ; 2 ; 1) et <b>v</b> = (0 ; 1 ; 1). Les vecteurs <b>w</b> = (1 ; 5 ; 3) et <b>w</b>′ = (1 ; 5 ; 4) sont-ils dans Vect(<b>u</b>, <b>v</b>)&nbsp;?',
    etapes:[{f:'<i>a</i>(1 ; 2 ; 1) + <i>b</i>(0 ; 1 ; 1) = (<i>a</i> ; 2<i>a</i> + <i>b</i> ; <i>a</i> + <i>b</i>).',w:'La combinaison avec des lettres.'},
     {f:'Pour <b>w</b> : <i>a</i> = 1, 2<i>a</i> + <i>b</i> = 5, <i>a</i> + <i>b</i> = 3.',w:'Trois équations, deux inconnues.'},
     {f:'Les deux premières donnent <i>a</i> = 1, <i>b</i> = 3. La troisième : 1 + 3 = 4 ≠ 3.',w:'Contradiction : aucun couple (a ; b) ne convient.'},
     {f:'Donc <b>w</b> ∉ Vect(<b>u</b>, <b>v</b>).',w:'Le plan engendré ne contient pas w.'},
     {f:'Pour <b>w</b>′ : <i>a</i> = 1, <i>b</i> = 3, et la troisième : 1 + 3 = 4 ✓. Donc <b>w</b>′ = <b>u</b> + 3<b>v</b> ∈ Vect(<b>u</b>, <b>v</b>).',w:'Contrôle : (1 ; 2 ; 1) + 3(0 ; 1 ; 1) = (1 ; 5 ; 4).'}],
    conclusion:'<b>w</b> ∉ Vect(<b>u</b>, <b>v</b>), <b>w</b>′ = <b>u</b> + 3<b>v</b> ∈ Vect(<b>u</b>, <b>v</b>). En général, le vecteur (<i>x</i> ; <i>y</i> ; <i>z</i>) est dans ce plan exactement quand <i>z</i> = <i>x</i> + (<i>y</i> − 2<i>x</i>), soit <i>x</i> − <i>y</i> + <i>z</i> = 0 : voilà son équation.'}},
  {h:'Complète pour rester dans le plan',p:'Soit <b>u</b> = (1 ; 1 ; 0) et <b>v</b> = (0 ; 1 ; 1). Pour quelle valeur de <i>c</i> le vecteur (2 ; 5 ; <i>c</i>) appartient-il à Vect(<b>u</b>, <b>v</b>)&nbsp;?',lab:'c =',ans:3,
   why:'a(1 ; 1 ; 0) + b(0 ; 1 ; 1) = (a ; a + b ; b). Il faut a = 2, puis a + b = 5 donne b = 3, et c = b = 3. Contrôle : 2u + 3v = (2 ; 5 ; 3).'},
  {h:'Somme directe et supplémentaires',
   p:'<p>Dans ℝ², les droites <i>D</i>₁ = ℝ(1 ; 0) et <i>D</i>₂ = ℝ(1 ; 2) vérifient <i>D</i>₁ + <i>D</i>₂ = ℝ², et chaque vecteur se décompose d’<b>une seule façon</b> en un vecteur de <i>D</i>₁ plus un vecteur de <i>D</i>₂. Ce n’est pas toujours le cas : si <i>F</i> et <i>G</i> se chevauchent, il y a plusieurs décompositions.</p><div class="def"><p>La somme <i>F</i> + <i>G</i> est <b>directe</b>, et on écrit <i>F</i> ⊕ <i>G</i>, si <b><i>F</i> ∩ <i>G</i> = {<b>0</b>}</b>. Si de plus <i>F</i> ⊕ <i>G</i> = <i>E</i>, on dit que <i>F</i> et <i>G</i> sont <b>supplémentaires</b> dans <i>E</i>.</p></div><div class="thm"><p>La somme est directe si et seulement si tout vecteur de <i>F</i> + <i>G</i> s’écrit <b>d’une seule manière</b> <b>f</b> + <b>g</b> avec <b>f</b> ∈ <i>F</i>, <b>g</b> ∈ <i>G</i>.</p></div><div class="why"><p>Supposons <i>F</i> ∩ <i>G</i> = {<b>0</b>} et <b>f</b> + <b>g</b> = <b>f</b>′ + <b>g</b>′. Alors <b>f</b> − <b>f</b>′ = <b>g</b>′ − <b>g</b> : le membre de gauche est dans <i>F</i>, celui de droite dans <i>G</i>, donc ce vecteur commun est dans <i>F</i> ∩ <i>G</i>, donc nul : <b>f</b> = <b>f</b>′ et <b>g</b> = <b>g</b>′. Réciproquement, si <b>x</b> ∈ <i>F</i> ∩ <i>G</i>, alors <b>x</b> = <b>x</b> + <b>0</b> = <b>0</b> + <b>x</b> sont deux décompositions ; l’unicité force <b>x</b> = <b>0</b>.</p></div><div class="ex"><p>Dans ℝ³, le plan <i>P</i> : <i>z</i> = 0 et la droite <i>D</i> = ℝ(1 ; 1 ; 1) : <i>P</i> ∩ <i>D</i> = {<b>0</b>} (un vecteur <i>t</i>(1 ; 1 ; 1) a <i>z</i> = <i>t</i> = 0 ⇒ <i>t</i> = 0), et (<i>x</i> ; <i>y</i> ; <i>z</i>) = (<i>x</i> − <i>z</i> ; <i>y</i> − <i>z</i> ; 0) + <i>z</i>(1 ; 1 ; 1). Donc <i>P</i> ⊕ <i>D</i> = ℝ³ : supplémentaires. <b>Contre-exemple :</b> deux plans de ℝ³ ne sont jamais en somme directe, leur intersection contient une droite.</p></div>',
   note:'Un sous-espace a en général plusieurs supplémentaires : dans ℝ², toute droite autre que D₁ est un supplémentaire de D₁. Ne dis pas « le » supplémentaire, mais « un » supplémentaire.'},
  {kind:'Méthode',h:'Décomposer un vecteur selon deux supplémentaires',
   p:'<b>Quand :</b> <i>E</i> = <i>F</i> ⊕ <i>G</i> et on veut écrire <b>w</b> = <b>f</b> + <b>g</b> avec <b>f</b> ∈ <i>F</i>, <b>g</b> ∈ <i>G</i>. <b>Comment :</b> 1) décris les éléments de <i>F</i> et de <i>G</i> avec des paramètres (par exemple <b>g</b> = <i>t</i>(1 ; 1 ; 1) pour une droite) ; 2) écris <b>f</b> = <b>w</b> − <b>g</b> et impose que <b>f</b> vérifie la condition qui définit <i>F</i> (son équation) : cela donne une équation en les paramètres ; 3) résous, puis calcule <b>f</b> et <b>g</b> ; 4) contrôle que <b>f</b> + <b>g</b> = <b>w</b> et que chacun est dans le bon sous-espace. Quand <i>F</i> et <i>G</i> sont donnés par des vecteurs qui les engendrent, c’est la méthode précédente : résoudre <i>a</i><b>u</b> + <i>b</i><b>v</b> = <b>w</b>.',
   demo:{enonce:'1) Dans ℝ², <i>F</i> = ℝ(1 ; 1), <i>G</i> = ℝ(1 ; −1), <b>w</b> = (3 ; 1). 2) Dans ℝ³, <i>P</i> : <i>z</i> = 0, <i>D</i> = ℝ(1 ; 1 ; 1), <b>w</b> = (2 ; 3 ; 5). Décompose <b>w</b>.',
    etapes:[{f:'1) <b>w</b> = <i>a</i>(1 ; 1) + <i>b</i>(1 ; −1) : <i>a</i> + <i>b</i> = 3 et <i>a</i> − <i>b</i> = 1.',w:'Les deux sous-espaces sont donnés par des vecteurs : système.'},
     {f:'En additionnant : 2<i>a</i> = 4, <i>a</i> = 2, <i>b</i> = 1. Donc <b>w</b> = (2 ; 2) + (1 ; −1).',w:'f = (2 ; 2) ∈ F et g = (1 ; −1) ∈ G ; leur somme est bien (3 ; 1).'},
     {f:'2) <b>g</b> = <i>t</i>(1 ; 1 ; 1) et <b>f</b> = <b>w</b> − <b>g</b> = (2 − <i>t</i> ; 3 − <i>t</i> ; 5 − <i>t</i>).',w:'On paramètre la droite, et f est ce qui reste.'},
     {f:'<b>f</b> ∈ <i>P</i> impose <i>z</i> = 0 : 5 − <i>t</i> = 0, donc <i>t</i> = 5.',w:'La condition de P donne l’équation en t.'},
     {f:'<b>f</b> = (−3 ; −2 ; 0) et <b>g</b> = (5 ; 5 ; 5). Contrôle : (−3 ; −2 ; 0) + (5 ; 5 ; 5) = (2 ; 3 ; 5).',w:'f a bien z = 0, g est bien un multiple de (1 ; 1 ; 1).'}],
    conclusion:'(3 ; 1) = (2 ; 2) + (1 ; −1) et (2 ; 3 ; 5) = (−3 ; −2 ; 0) + (5 ; 5 ; 5). Chaque décomposition est unique parce que la somme est directe.'}},
  {h:'Décompose dans ℝ³',p:'Dans ℝ³, <i>F</i> : <i>x</i> + <i>y</i> + <i>z</i> = 0 et <i>G</i> = ℝ(1 ; 1 ; 1) sont supplémentaires. On écrit <b>w</b> = (5 ; 2 ; −1) = <b>f</b> + <i>t</i>(1 ; 1 ; 1) avec <b>f</b> ∈ <i>F</i>. Que vaut <i>t</i>&nbsp;?',lab:'t =',ans:2,
   why:'f = (5 − t ; 2 − t ; −1 − t) doit vérifier x + y + z = 0 : 6 − 3t = 0, donc t = 2. Alors f = (3 ; 0 ; −3) et 3 + 0 − 3 = 0.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:'<div class="keep"><ul><li>Un sous-espace vectoriel de <i>E</i> est une partie qui est elle-même un espace vectoriel pour les lois de <i>E</i>.</li><li>Critère : <i>F</i> est un sous-espace ⇔ <b>0</b> ∈ <i>F</i> et λ<b>u</b> + μ<b>v</b> ∈ <i>F</i> pour tous <b>u</b>, <b>v</b> ∈ <i>F</i>, λ, μ ∈ ℝ. Preuve type : regrouper par λ et μ pour retrouver la condition connue.</li><li>Trois façons de rater : <b>0</b> ∉ <i>F</i> (droite hors de l’origine, constante dans l’équation), un multiple sort (demi-plan, inégalité), une somme sort (réunion de deux droites, carré, produit).</li><li><i>F</i> ∩ <i>G</i> est un sous-espace. <i>F</i> ∪ <i>G</i> n’en est pas un en général.</li><li><i>F</i> + <i>G</i> = {<b>f</b> + <b>g</b>} est le plus petit sous-espace contenant <i>F</i> et <i>G</i>.</li><li>Vect(<b>v</b>₁, …, <b>v</b>ₖ) = ensemble des combinaisons linéaires : le plus petit sous-espace contenant les <b>v</b>ᵢ. Test d’appartenance : résoudre <i>a</i><b>u</b> + <i>b</i><b>v</b> = <b>w</b> et reporter dans l’équation restante.</li><li>Somme directe <i>F</i> ⊕ <i>G</i> : <i>F</i> ∩ <i>G</i> = {<b>0</b>}, ce qui équivaut à l’unicité de la décomposition <b>f</b> + <b>g</b>. Supplémentaires : <i>F</i> ⊕ <i>G</i> = <i>E</i>. Décomposer : paramétrer <i>G</i>, imposer la condition de <i>F</i> à <b>w</b> − <b>g</b>.</li></ul></div>'},
  {kind:'Problème',h:'Fonctions paires et fonctions impaires',
   p:'Dans <i>E</i> = F(ℝ, ℝ), on note 𝒫 l’ensemble des fonctions <b>paires</b> (<i>f</i>(−<i>x</i>) = <i>f</i>(<i>x</i>) pour tout <i>x</i>) et 𝓘 celui des fonctions <b>impaires</b> (<i>f</i>(−<i>x</i>) = −<i>f</i>(<i>x</i>)). On veut montrer que 𝒫 et 𝓘 sont deux sous-espaces supplémentaires de <i>E</i>, puis décomposer la fonction <i>f</i>(<i>x</i>) = <i>x</i>³ + 2<i>x</i>² − <i>x</i> + 4.',
   fig:(()=>{ const P=plane({x:[-3,3],y:[-6,12],lab:3}); P.fn(x=>x*x*x+2*x*x-x+4,{c:'var(--accent)',w:4}).fn(x=>2*x*x+4,{c:'var(--math)',w:2.5,dash:true}).fn(x=>x*x*x-x,{c:'var(--spark)',w:2.5,dash:true}); P.text(-2.9,11,'f',{c:'var(--accent)'}).text(1.6,10.5,'partie paire',{c:'var(--math)',s:12}).text(1.3,-4.5,'partie impaire',{c:'var(--spark)',s:12}); return P.svg(); })(),
   parts:[
    {q:'a) Pourquoi 𝒫 est-il un sous-espace de <i>E</i>&nbsp;?',opts:['Parce que <i>x</i>² est paire','Parce que la fonction nulle est paire, et si <i>f</i>, <i>g</i> sont paires, (λ<i>f</i> + μ<i>g</i>)(−<i>x</i>) = λ<i>f</i>(−<i>x</i>) + μ<i>g</i>(−<i>x</i>) = λ<i>f</i>(<i>x</i>) + μ<i>g</i>(<i>x</i>) = (λ<i>f</i> + μ<i>g</i>)(<i>x</i>)','Parce que le produit de deux fonctions paires est pair','Parce que toute fonction est paire ou impaire'],ans:1,
     hint:'Applique le critère : 0 ∈ 𝒫, puis stabilité par combinaison linéaire, en calculant en −x.',why:'C’est exactement le critère. Le même calcul avec un signe − montre que 𝓘 est aussi un sous-espace. (Le produit n’a rien à voir avec la structure vectorielle, et x ↦ x + 1 n’est ni paire ni impaire.)'},
    {q:'b) Pourquoi 𝒫 ∩ 𝓘 = {0}&nbsp;?',opts:['Parce qu’une fonction ne peut pas être continue et paire','Si <i>f</i> est paire et impaire, <i>f</i>(<i>x</i>) = <i>f</i>(−<i>x</i>) = −<i>f</i>(<i>x</i>), donc 2<i>f</i>(<i>x</i>) = 0 pour tout <i>x</i>','Parce que 𝒫 et 𝓘 sont disjoints','Parce que la fonction nulle n’est ni paire ni impaire'],ans:1,
     hint:'Écris les deux conditions pour la même fonction et compare.',why:'f(x) = −f(x) force f(x) = 0 en tout point : f est la fonction nulle. 𝒫 et 𝓘 ne sont pas disjoints (ils partagent 0), et la somme 𝒫 + 𝓘 est directe.'},
    {q:'c) On pose <i>p</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) + <i>f</i>(−<i>x</i>))/2 et <i>i</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) − <i>f</i>(−<i>x</i>))/2, de sorte que <i>f</i> = <i>p</i> + <i>i</i> avec <i>p</i> paire et <i>i</i> impaire. Pour <i>f</i>(<i>x</i>) = <i>x</i>³ + 2<i>x</i>² − <i>x</i> + 4, que vaut <i>p</i>(1)&nbsp;?',lab:'p(1) =',ans:6,hint:'Calcule f(1) et f(−1), ou repère les monômes de degré pair.',why:'f(1) = 6 et f(−1) = −1 + 2 + 1 + 4 = 6, donc p(1) = 6. En fait p(x) = 2x² + 4 : les monômes de degré pair.'},
    {q:'d) Que vaut <i>i</i>(3)&nbsp;?',lab:'i(3) =',ans:24,hint:'i(x) regroupe les monômes de degré impair.',why:'i(x) = x³ − x, donc i(3) = 27 − 3 = 24. Contrôle : f(3) = 27 + 18 − 3 + 4 = 46 et f(−3) = −27 + 18 + 3 + 4 = −2 ; (46 − (−2))/2 = 24.'},
    {q:'e) Pourquoi la décomposition <i>f</i> = <i>p</i> + <i>i</i> est-elle la seule possible&nbsp;?',opts:['Parce que <i>f</i> est un polynôme','Parce que la somme 𝒫 + 𝓘 est directe : 𝒫 ∩ 𝓘 = {0}','Parce que <i>p</i>(0) = <i>f</i>(0)','Parce que les fonctions paires sont plus nombreuses'],ans:1,
     hint:'Relis le théorème sur les sommes directes.',why:'Dans une somme directe, chaque vecteur a une unique décomposition : deux écritures p + i = p′ + i′ donneraient p − p′ = i′ − i ∈ 𝒫 ∩ 𝓘 = {0}.'},
   ],
   sol:'𝒫 et 𝓘 contiennent la fonction nulle et sont stables par combinaison linéaire (on calcule en −<i>x</i>) : ce sont des sous-espaces.<br>Si <i>f</i> ∈ 𝒫 ∩ 𝓘, alors <i>f</i>(<i>x</i>) = <i>f</i>(−<i>x</i>) = −<i>f</i>(<i>x</i>), donc <i>f</i> = 0 : la somme est directe.<br>Pour toute <i>f</i>, <i>p</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) + <i>f</i>(−<i>x</i>))/2 est paire, <i>i</i>(<i>x</i>) = (<i>f</i>(<i>x</i>) − <i>f</i>(−<i>x</i>))/2 est impaire, et <i>p</i> + <i>i</i> = <i>f</i>. Donc 𝒫 + 𝓘 = <i>E</i> : <b><i>E</i> = 𝒫 ⊕ 𝓘</b>.<br>Pour <i>f</i>(<i>x</i>) = <i>x</i>³ + 2<i>x</i>² − <i>x</i> + 4 : <i>p</i>(<i>x</i>) = 2<i>x</i>² + 4 et <i>i</i>(<i>x</i>) = <i>x</i>³ − <i>x</i>, d’où <i>p</i>(1) = 6 et <i>i</i>(3) = 24. Pour un polynôme, la partie paire regroupe les monômes de degré pair, la partie impaire ceux de degré impair.'},
  {kind:'Problème',h:'Un plan qui dépend d’un paramètre',
   p:'Pour un réel <i>k</i>, on note <i>F</i>ₖ le plan vectoriel de ℝ³ d’équation <i>x</i> + <i>k</i><i>y</i> − <i>z</i> = 0, et <i>G</i> = ℝ(1 ; 1 ; 1) la droite dirigée par (1 ; 1 ; 1). On cherche pour quelles valeurs de <i>k</i> la droite et le plan sont supplémentaires, puis on décompose un vecteur quand c’est le cas.',
   fig:(()=>{ const S=space({r:5,az:28,el:22}); const f=(x,y)=>[x,y,x+2*y]; S.poly([f(-2,-1.2),f(2,-1.2),f(2,1.2),f(-2,1.2)],{fill:'var(--accent)',fo:.12,c:'var(--muted)',w:1.5});
     S.seg([-2.6,-2.6,-2.6],[2.6,2.6,2.6],{c:'var(--ok)',w:2.5,dash:true}); S.arrow([0,0,0],[1,1,1],{c:'var(--ok)',w:3}); S.text([1,1,1],'(1 ; 1 ; 1)',{c:'var(--ok)',dx:6,dy:-4}); S.text(f(1.6,-1.1),'F₂ : x + 2y − z = 0',{dx:-70,dy:16,s:12}); S.dot([0,0,0],{r:4,c:'var(--ink)'}); return S.svg(); })(),
   parts:[
    {q:'a) Pour quelle valeur de <i>k</i> le vecteur (1 ; 1 ; 1) appartient-il à <i>F</i>ₖ&nbsp;?',lab:'k =',ans:0,hint:'Remplace (x ; y ; z) par (1 ; 1 ; 1) dans l’équation.',why:'1 + k − 1 = k, qui vaut 0 seulement pour k = 0. Pour k = 0, G ⊂ F₀ et la somme F₀ + G = F₀ n’est pas tout ℝ³.'},
    {q:'b) Pour <i>k</i> ≠ 0, pourquoi <i>F</i>ₖ ∩ <i>G</i> = {<b>0</b>}&nbsp;?',opts:['Parce qu’un plan et une droite ne se coupent jamais','Un vecteur de <i>G</i> s’écrit <i>t</i>(1 ; 1 ; 1) ; il est dans <i>F</i>ₖ si <i>t</i> + <i>kt</i> − <i>t</i> = <i>kt</i> = 0, donc <i>t</i> = 0','Parce que <i>F</i>ₖ contient (1 ; 1 ; 1)','Parce que <i>k</i> ≠ 0 rend l’équation impossible'],ans:1,
     hint:'Paramètre G par t et reporte dans l’équation de Fₖ.',why:'kt = 0 avec k ≠ 0 force t = 0 : le seul vecteur commun est 0. La somme Fₖ + G est donc directe.'},
    {q:'c) On prend <i>k</i> = 2 et <b>w</b> = (4 ; 1 ; 0). On écrit <b>w</b> = <b>f</b> + <i>t</i>(1 ; 1 ; 1) avec <b>f</b> ∈ <i>F</i>₂. Que vaut <i>t</i>&nbsp;?',lab:'t =',ans:3,hint:'f = (4 − t ; 1 − t ; −t) doit vérifier x + 2y − z = 0.',why:'(4 − t) + 2(1 − t) − (−t) = 6 − 2t = 0, donc t = 3.'},
    {q:'d) Quelle est la première coordonnée de <b>f</b>&nbsp;?',lab:'x =',ans:1,hint:'f = w − 3(1 ; 1 ; 1).',why:'f = (4 − 3 ; 1 − 3 ; 0 − 3) = (1 ; −2 ; −3). Contrôle : 1 + 2(−2) − (−3) = 0, et f + (3 ; 3 ; 3) = (4 ; 1 ; 0).'},
    {q:'e) Pour <i>k</i> ≠ 0, pourquoi <i>F</i>ₖ + <i>G</i> = ℝ³&nbsp;?',opts:['Parce que <i>F</i>ₖ est un plan et <i>G</i> une droite','Pour tout <b>w</b>, le réel <i>t</i> = (<i>w</i>₁ + <i>k</i><i>w</i>₂ − <i>w</i>₃)/<i>k</i> est défini, et <b>w</b> − <i>t</i>(1 ; 1 ; 1) vérifie l’équation de <i>F</i>ₖ','Parce que (1 ; 1 ; 1) ∈ <i>F</i>ₖ','Parce que l’intersection est {<b>0</b>}'],ans:1,
     hint:'Refais le calcul de c) avec w = (w₁ ; w₂ ; w₃) quelconque : quelle équation obtient-on en t ?',why:'(w₁ − t) + k(w₂ − t) − (w₃ − t) = (w₁ + kw₂ − w₃) − kt = 0 se résout dès que k ≠ 0. Chaque w se décompose : la somme est tout ℝ³. L’intersection réduite à {0} ne suffit pas à elle seule (deux droites de ℝ³ ont une intersection nulle sans engendrer l’espace).'},
   ],
   sol:'(1 ; 1 ; 1) ∈ <i>F</i>ₖ ⇔ 1 + <i>k</i> − 1 = 0 ⇔ <i>k</i> = 0. Pour <i>k</i> = 0, <i>G</i> ⊂ <i>F</i>₀ et la somme n’est ni directe ni égale à ℝ³.<br>Pour <i>k</i> ≠ 0 : un vecteur <i>t</i>(1 ; 1 ; 1) de <i>G</i> est dans <i>F</i>ₖ si <i>kt</i> = 0, donc <i>t</i> = 0 : <i>F</i>ₖ ∩ <i>G</i> = {<b>0</b>}. Et pour tout <b>w</b>, on cherche <i>t</i> tel que <b>w</b> − <i>t</i>(1 ; 1 ; 1) ∈ <i>F</i>ₖ : (<i>w</i>₁ + <i>k</i><i>w</i>₂ − <i>w</i>₃) − <i>kt</i> = 0 a l’unique solution <i>t</i> = (<i>w</i>₁ + <i>k</i><i>w</i>₂ − <i>w</i>₃)/<i>k</i>. Donc <b><i>F</i>ₖ ⊕ <i>G</i> = ℝ³ exactement quand <i>k</i> ≠ 0</b>.<br>Pour <i>k</i> = 2 et <b>w</b> = (4 ; 1 ; 0) : <i>t</i> = (4 + 2 − 0)/2 = 3, <b>f</b> = (1 ; −2 ; −3). Contrôle : 1 − 4 + 3 = 0 et (1 ; −2 ; −3) + (3 ; 3 ; 3) = (4 ; 1 ; 0).'},
]},
);

COURS.push(
/* ===================== 4. COMBINAISONS LINÉAIRES, BASES ET DIMENSION ===================== */
{subj:'gred',sem:'lin',id:'gred-bases',h:'Combinaisons linéaires, bases et dimension',p:'Familles génératrices, familles libres et liées, bases et coordonnées, le lemme qui compare libre et génératrice, la dimension, le théorème de la base incomplète, la dimension des sous-espaces et la formule de Grassmann.',steps:[
  {h:'Familles génératrices',
   p:Rappel('Vect(<b>v</b>₁, …, <b>v</b>ₖ) est l’ensemble des combinaisons linéaires λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ : le plus petit sous-espace qui contient les <b>v</b>ᵢ.')+'<p>Pour décrire un espace vectoriel, on aimerait n’en donner que quelques vecteurs à partir desquels on reconstruit tous les autres par combinaison. C’est l’idée de famille génératrice.</p><div class="def"><p>Une famille (<b>v</b>₁, …, <b>v</b>ₖ) de vecteurs de <i>E</i> est <b>génératrice</b> de <i>E</i> si <b>Vect(<b>v</b>₁, …, <b>v</b>ₖ) = <i>E</i></b> : tout vecteur de <i>E</i> est une combinaison linéaire des <b>v</b>ᵢ.</p></div><div class="ex"><p>Dans ℝ³, la famille (<b>e</b>₁, <b>e</b>₂, <b>e</b>₃) = ((1 ; 0 ; 0), (0 ; 1 ; 0), (0 ; 0 ; 1)) est génératrice : (<i>x</i> ; <i>y</i> ; <i>z</i>) = <i>x</i><b>e</b>₁ + <i>y</i><b>e</b>₂ + <i>z</i><b>e</b>₃. Dans ℝ[<i>x</i>]≤₂, la famille (1, <i>x</i>, <i>x</i>²) est génératrice : <i>a</i> + <i>bx</i> + <i>cx</i>² est une combinaison de ces trois polynômes. Dans ℝ², ((1 ; 0), (0 ; 1), (1 ; 1)) est génératrice aussi, mais avec un vecteur de trop : (1 ; 1) se fabrique déjà avec les deux premiers.</p></div><div class="idea"><p>Une famille génératrice, c’est un « jeu de briques » suffisant. On peut en avoir plus que nécessaire, et il y a beaucoup de choix possibles. Pour vérifier qu’une famille engendre ℝⁿ, on résout l’équation Σλᵢ<b>v</b>ᵢ = <b>w</b> pour un <b>w</b> quelconque, avec des lettres.</p></div><div class="warn"><p>Une famille de deux vecteurs n’engendre jamais ℝ³ : leurs combinaisons restent dans un plan (ou une droite). On le prouvera plus bas avec le lemme fondamental.</p></div>'},
  {h:'Famille libre : une seule façon d’écrire 0',
   p:'<p>Dans ((1 ; 0), (0 ; 1), (1 ; 1)), le vecteur nul s’écrit de deux façons : 0·(1 ; 0) + 0·(0 ; 1) + 0·(1 ; 1), mais aussi 1·(1 ; 0) + 1·(0 ; 1) − 1·(1 ; 1). Cette redondance a un nom.</p><div class="def"><p>La famille (<b>v</b>₁, …, <b>v</b>ₖ) est <b>libre</b> (ses vecteurs sont <b>linéairement indépendants</b>) si la seule combinaison nulle est la combinaison triviale :<br><b>λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ = <b>0</b> ⇒ λ₁ = … = λₖ = 0</b>.<br>Sinon, elle est <b>liée</b> : il existe des coefficients non tous nuls dont la combinaison est <b>0</b>.</p></div><div class="idea"><p>« Libre » signifie qu’aucune brique n’est fabricable avec les autres : pas de redondance. Pour tester, on <b>suppose</b> une combinaison nulle et on cherche à démontrer que tous les coefficients sont nuls. Si on y arrive, libre ; si on trouve des coefficients non nuls qui marchent, liée.</p></div><div class="ex"><p>Une famille d’un seul vecteur (<b>v</b>) est libre si et seulement si <b>v</b> ≠ <b>0</b> (car λ<b>v</b> = <b>0</b> avec <b>v</b> ≠ <b>0</b> force λ = 0). Deux vecteurs forment une famille libre si et seulement s’ils ne sont pas colinéaires. Toute famille contenant <b>0</b> est liée : 1·<b>0</b> + 0·(les autres) = <b>0</b> avec un coefficient 1.</p></div><div class="warn"><p>« λ₁ = … = λₖ = 0 ⇒ combinaison nulle » est toujours vrai et ne prouve rien. C’est le sens inverse qui compte : <b>de</b> la combinaison nulle <b>vers</b> la nullité des coefficients.</p></div>'},
  {kind:'Méthode',h:'Tester si une famille est libre',
   p:'<b>Quand :</b> on demande si (<b>v</b>₁, …, <b>v</b>ₖ) est libre ou liée. <b>Comment :</b> 1) écris λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ = <b>0</b> avec des inconnues λᵢ ; 2) traduis coordonnée par coordonnée (ou coefficient par coefficient pour des polynômes) : un système linéaire <b>homogène</b> ; 3) résous-le par substitution ou combinaison. Si la seule solution est λ₁ = … = λₖ = 0, la famille est <b>libre</b> ; si tu trouves une solution non nulle, écris-la explicitement : c’est la <b>relation</b> qui prouve que la famille est <b>liée</b>. <b>Raccourcis :</b> un vecteur nul, deux vecteurs colinéaires ou un vecteur visiblement somme des autres donnent tout de suite « liée ». Dans ℝ², deux vecteurs sont libres si <i>u</i>₁<i>v</i>₂ − <i>u</i>₂<i>v</i>₁ ≠ 0.',
   demo:{enonce:'Dans ℝ³, la famille ((1 ; 1 ; 0), (0 ; 1 ; 1), (1 ; 0 ; 1)) est-elle libre ? Et ((1 ; 2 ; 3), (2 ; 1 ; 0), (3 ; 3 ; 3))&nbsp;?',
    etapes:[{f:'<i>a</i>(1 ; 1 ; 0) + <i>b</i>(0 ; 1 ; 1) + <i>c</i>(1 ; 0 ; 1) = (<i>a</i> + <i>c</i> ; <i>a</i> + <i>b</i> ; <i>b</i> + <i>c</i>) = (0 ; 0 ; 0).',w:'On pose la combinaison nulle avec des inconnues.'},
     {f:'Système : <i>a</i> + <i>c</i> = 0, <i>a</i> + <i>b</i> = 0, <i>b</i> + <i>c</i> = 0. Les deux premières donnent <i>c</i> = −<i>a</i> et <i>b</i> = −<i>a</i> ; la troisième : −2<i>a</i> = 0.',w:'Substitution.'},
     {f:'Donc <i>a</i> = 0, puis <i>b</i> = <i>c</i> = 0 : la première famille est <b>libre</b>.',w:'Seule la combinaison triviale est nulle.'},
     {f:'Seconde famille : on remarque (1 ; 2 ; 3) + (2 ; 1 ; 0) = (3 ; 3 ; 3).',w:'Raccourci : un vecteur est la somme des deux autres.'},
     {f:'Relation : 1·(1 ; 2 ; 3) + 1·(2 ; 1 ; 0) − 1·(3 ; 3 ; 3) = <b>0</b>, avec des coefficients non nuls.',w:'On écrit la combinaison nulle non triviale : la famille est liée.'}],
    conclusion:'La première famille est <b>libre</b>, la seconde est <b>liée</b>. Sans le raccourci, le système de la seconde aurait donné une infinité de solutions, par exemple (1 ; 1 ; −1).'}},
  {h:'Libre ou liée ?',p:'Laquelle de ces familles est <b>libre</b>&nbsp;?',
   opts:['((1 ; 2), (2 ; 4))','((1 ; 0 ; 1), (0 ; 1 ; 0), (1 ; 1 ; 1))','((1 ; 1), (1 ; −1))','((1 ; 2 ; 3), (0 ; 0 ; 0))'],ans:2,
   why:'a(1 ; 1) + b(1 ; −1) = (a + b ; a − b) = 0 force a = b = 0 (ou : 1·(−1) − 1·1 = −2 ≠ 0). Les autres : (2 ; 4) = 2(1 ; 2) ; (1 ; 1 ; 1) = (1 ; 0 ; 1) + (0 ; 1 ; 0) ; et une famille qui contient 0 est liée.'},
  {h:'Liée ⇔ un vecteur s’exprime avec les autres',
   p:'<p>La définition de « liée » parle d’une combinaison nulle. Voici ce qu’elle dit concrètement.</p><div class="prop"><p>Une famille (<b>v</b>₁, …, <b>v</b>ₖ) avec <i>k</i> ≥ 2 est liée <b>si et seulement si</b> l’un de ses vecteurs est une combinaison linéaire des autres.</p></div><div class="why"><p>Sens direct : supposons λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ = <b>0</b> avec, disons, λ₁ ≠ 0. On isole : λ₁<b>v</b>₁ = −λ₂<b>v</b>₂ − … − λₖ<b>v</b>ₖ, puis on multiplie par le scalaire 1/λ₁ (possible car λ₁ ≠ 0) : <b>v</b>₁ = −(λ₂/λ₁)<b>v</b>₂ − … − (λₖ/λ₁)<b>v</b>ₖ. Le vecteur <b>v</b>₁ s’exprime avec les autres. Sens réciproque : si <b>v</b>₁ = μ₂<b>v</b>₂ + … + μₖ<b>v</b>ₖ, alors 1·<b>v</b>₁ − μ₂<b>v</b>₂ − … − μₖ<b>v</b>ₖ = <b>0</b> est une combinaison nulle dont le premier coefficient vaut 1 ≠ 0 : la famille est liée.</p></div><div class="idea"><p>Liée = redondante : on peut retirer un vecteur sans changer Vect. En effet, si <b>v</b>₁ est combinaison des autres, toute combinaison des <b>v</b>ᵢ se réécrit sans <b>v</b>₁, donc Vect(<b>v</b>₁, …, <b>v</b>ₖ) = Vect(<b>v</b>₂, …, <b>v</b>ₖ). Libre = sans redondance : retirer un vecteur fait rétrécir Vect.</p></div><div class="warn"><p>« L’un des vecteurs » : pas n’importe lequel. Dans ((1 ; 0), (2 ; 0), (0 ; 1)), le vecteur (0 ; 1) n’est pas combinaison des deux autres, mais (2 ; 0) = 2(1 ; 0) l’est. La famille est liée.</p></div>'},
  {h:'Dans le plan, trois vecteurs sont toujours liés',
   p:'<p>On fixe <b>u</b> = (2 ; 1) et <b>v</b> = (1 ; 2), qui forment une famille libre. Quel que soit le troisième vecteur <b>w</b>, la famille (<b>u</b>, <b>v</b>, <b>w</b>) est liée : <b>w</b> s’écrit <i>a</i><b>u</b> + <i>b</i><b>v</b>, d’après le théorème du premier chapitre (2 · 2 − 1 · 1 = 3 ≠ 0). Déplace <b>w</b> et lis la relation.</p><div class="idea"><p>Deux vecteurs libres du plan forment déjà un quadrillage qui atteint tout : un troisième vecteur, quel qu’il soit, est forcément « fabricable » avec les deux premiers. C’est la redondance qui définit une famille liée.</p></div>',
   params:[{id:'x',l:'w₁',min:-4,max:4,v:3},{id:'y',l:'w₂',min:-4,max:4,v:-3}],
   draw:v=>{ const a=(2*v.x-v.y)/3, b=(2*v.y-v.x)/3; const P=comb([2,1],[1,2],a,b,{para:true,lines:true}); P.dot(v.x,v.y,{r:6,c:'var(--bad)',l:'w',dx:9,dy:-8}); return P.svg(); },
   info:v=>{ const a=(2*v.x-v.y)/3, b=(2*v.y-v.x)/3; return `<b>w</b> = ${V2(v.x,v.y)} = ${fmt(a)}·<b>u</b> + ${fmt(b)}·<b>v</b>, donc ${fmt(a)}·<b>u</b> + ${fmt(b)}·<b>v</b> − 1·<b>w</b> = <b>0</b> : combinaison nulle à coefficients non tous nuls.`; },
   note:'Ici a = (2w₁ − w₂)/3 et b = (2w₂ − w₁)/3, formules obtenues en résolvant le système. Même pour w = 0, la famille est liée (coefficient 1 devant w). Le lemme plus bas généralise : dans ℝⁿ, n + 1 vecteurs sont toujours liés.'},
  {h:'Base et coordonnées',
   p:'<p>Une famille génératrice fournit assez de briques ; une famille libre n’a pas de brique en trop. Les deux à la fois : c’est l’outil idéal.</p><div class="def"><p>Une <b>base</b> de <i>E</i> est une famille <b>libre et génératrice</b>. Si (<b>e</b>₁, …, <b>e</b>ₙ) est une base, tout vecteur <b>w</b> s’écrit <b>w</b> = <i>x</i>₁<b>e</b>₁ + … + <i>x</i>ₙ<b>e</b>ₙ, et les réels (<i>x</i>₁ ; … ; <i>x</i>ₙ) sont les <b>coordonnées</b> de <b>w</b> dans cette base.</p></div><div class="thm"><p>Dans une base, les coordonnées d’un vecteur sont <b>uniques</b>.</p></div><div class="why"><p>Existence : la famille est génératrice. Unicité : si <b>w</b> = Σ<i>x</i>ᵢ<b>e</b>ᵢ = Σ<i>y</i>ᵢ<b>e</b>ᵢ, alors en soustrayant Σ(<i>x</i>ᵢ − <i>y</i>ᵢ)<b>e</b>ᵢ = <b>0</b>. La famille étant libre, tous les coefficients <i>x</i>ᵢ − <i>y</i>ᵢ sont nuls : <i>x</i>ᵢ = <i>y</i>ᵢ. La liberté sert exactement à cela : garantir qu’il n’y a qu’une écriture.</p></div><div class="ex"><p><b>Bases canoniques.</b> Dans ℝⁿ : (<b>e</b>₁, …, <b>e</b>ₙ) où <b>e</b>ᵢ a un 1 en position <i>i</i> et des 0 ailleurs ; les coordonnées de (<i>x</i>₁ ; … ; <i>x</i>ₙ) sont ses propres composantes. Dans ℝ[<i>x</i>]≤ₙ : (1, <i>x</i>, …, <i>x</i>ⁿ), les coordonnées sont les coefficients. Dans M₂(ℝ) : les quatre matrices <i>E</i>₁₁, <i>E</i>₁₂, <i>E</i>₂₁, <i>E</i>₂₂ ayant un seul 1 ; les coordonnées de '+mat([['<i>a</i>','<i>b</i>'],['<i>c</i>','<i>d</i>']])+' sont (<i>a</i> ; <i>b</i> ; <i>c</i> ; <i>d</i>). Mais ℝ² a bien d’autres bases : ((1 ; 1), (1 ; −1)) par exemple, où (3 ; 1) a pour coordonnées (2 ; 1), car (3 ; 1) = 2(1 ; 1) + 1(1 ; −1).</p></div>',
   note:'Les coordonnées dépendent de la base. Le même vecteur (3 ; 1) a pour coordonnées (3 ; 1) dans la base canonique et (2 ; 1) dans la base ((1 ; 1), (1 ; −1)). Toujours préciser la base.'},
  {kind:'Méthode',h:'Trouver les coordonnées dans une base',
   p:'<b>Quand :</b> on connaît une base (<b>e</b>₁, …, <b>e</b>ₙ) et un vecteur <b>w</b>, et on veut ses coordonnées. <b>Comment :</b> 1) écris <b>w</b> = <i>x</i>₁<b>e</b>₁ + … + <i>x</i>ₙ<b>e</b>ₙ avec des inconnues ; 2) traduis coordonnée par coordonnée (ou coefficient par coefficient) : un système à <i>n</i> équations et <i>n</i> inconnues ; 3) résous ; 4) contrôle en recalculant la combinaison. Le théorème garantit une solution unique si la famille est vraiment une base. <b>Astuce pour les polynômes</b> : une base du type (1, <i>x</i> − <i>c</i>, (<i>x</i> − <i>c</i>)², …) se traite par le changement de variable <i>y</i> = <i>x</i> − <i>c</i>, ou en identifiant les coefficients du plus haut degré au plus bas.',
   demo:{enonce:'1) Coordonnées de <b>w</b> = (3 ; 1 ; 2) dans la base ((1 ; 1 ; 0), (0 ; 1 ; 1), (1 ; 0 ; 1)) de ℝ³. 2) Coordonnées de <i>P</i> = <i>x</i>² + <i>x</i> + 1 dans la base (1, <i>x</i> − 1, (<i>x</i> − 1)²) de ℝ[<i>x</i>]≤₂.',
    etapes:[{f:'1) <i>a</i>(1 ; 1 ; 0) + <i>b</i>(0 ; 1 ; 1) + <i>c</i>(1 ; 0 ; 1) = (<i>a</i> + <i>c</i> ; <i>a</i> + <i>b</i> ; <i>b</i> + <i>c</i>) = (3 ; 1 ; 2).',w:'Trois équations : a + c = 3, a + b = 1, b + c = 2.'},
     {f:'En additionnant les trois : 2(<i>a</i> + <i>b</i> + <i>c</i>) = 6, donc <i>a</i> + <i>b</i> + <i>c</i> = 3. Alors <i>b</i> = 3 − 3 = 0, <i>c</i> = 3 − 1 = 2, <i>a</i> = 3 − 2 = 1.',w:'Une combinaison astucieuse des lignes ; la substitution marche aussi.'},
     {f:'Contrôle : 1(1 ; 1 ; 0) + 0(0 ; 1 ; 1) + 2(1 ; 0 ; 1) = (3 ; 1 ; 2). Coordonnées (1 ; 0 ; 2).',w:'On recalcule toujours.'},
     {f:'2) <i>a</i> + <i>b</i>(<i>x</i> − 1) + <i>c</i>(<i>x</i> − 1)² = <i>c</i><i>x</i>² + (<i>b</i> − 2<i>c</i>)<i>x</i> + (<i>a</i> − <i>b</i> + <i>c</i>).',w:'On développe et on identifie les coefficients avec x² + x + 1.'},
     {f:'<i>c</i> = 1 ; <i>b</i> − 2 = 1 donne <i>b</i> = 3 ; <i>a</i> − 3 + 1 = 1 donne <i>a</i> = 3. Contrôle : 3 + 3(<i>x</i> − 1) + (<i>x</i> − 1)² = <i>x</i>² + <i>x</i> + 1.',w:'Du plus haut degré au plus bas : chaque équation n’a qu’une inconnue nouvelle.'}],
    conclusion:'(3 ; 1 ; 2) a pour coordonnées <b>(1 ; 0 ; 2)</b> dans la première base ; <i>x</i>² + <i>x</i> + 1 a pour coordonnées <b>(3 ; 3 ; 1)</b> dans (1, <i>x</i> − 1, (<i>x</i> − 1)²).'}},
  {h:'Coordonnées dans une base du plan',p:'Dans la base ((1 ; 3), (2 ; 1)) de ℝ², quelle est la première coordonnée <i>a</i> de <b>w</b> = (4 ; 7)&nbsp;?',lab:'a =',ans:2,
   why:'a + 2b = 4 et 3a + b = 7. De la première, a = 4 − 2b ; dans la seconde : 12 − 6b + b = 7, donc b = 1 et a = 2. Contrôle : 2(1 ; 3) + (2 ; 1) = (4 ; 7).'},
  {kind:'Pratique',h:'Règle les coordonnées',p:'Dans la base <b>u</b> = (1 ; 2), <b>v</b> = (−1 ; 1), règle les coordonnées (<i>a</i> ; <i>b</i>) pour que <i>a</i><b>u</b> + <i>b</i><b>v</b> tombe sur le point rouge <b>w</b> = (1 ; 5).',
   params:[{id:'a',l:'a',min:-3,max:3,step:.5,v:1},{id:'b',l:'b',min:-3,max:3,step:.5,v:1}],
   draw:v=>comb([1,2],[-1,1],v.a,v.b,{para:true,lines:true,target:[1,5],tl:'w'}).svg(),
   info:v=>`<i>a</i><b>u</b> + <i>b</i><b>v</b> = ${V2(v.a-v.b,2*v.a+v.b)}`,
   ok:v=>v.a===2&&v.b===1,
   why:'a − b = 1 et 2a + b = 5. En additionnant : 3a = 6, donc a = 2 et b = 1. Les coordonnées de (1 ; 5) dans cette base sont (2 ; 1).'},
  {h:'Le lemme fondamental : libre ≤ génératrice',
   p:'<p>Toutes les bases de ℝ² ont deux vecteurs, celles de ℝ³ en ont trois. Est-ce un hasard ? Non : c’est la conséquence d’un lemme qui compare les familles libres et les familles génératrices.</p><div class="thm"><p>Si une famille de <i>n</i> vecteurs engendre <i>E</i>, alors toute famille libre de <i>E</i> a <b>au plus <i>n</i></b> éléments. Conséquence : <b>deux bases de <i>E</i> ont le même nombre d’éléments</b>.</p></div><div class="why"><p>Idée de la preuve. Soit (<b>g</b>₁, …, <b>g</b>ₙ) génératrice et (<b>v</b>₁, …, <b>v</b>ₘ) une famille avec <i>m</i> &gt; <i>n</i> : montrons qu’elle est liée. Chaque <b>v</b>ⱼ s’écrit comme combinaison des <b>g</b>ᵢ. Une combinaison μ₁<b>v</b>₁ + … + μₘ<b>v</b>ₘ se développe alors en une combinaison des <b>g</b>ᵢ ; pour qu’elle soit nulle, il suffit que les <i>n</i> coefficients devant <b>g</b>₁, …, <b>g</b>ₙ soient nuls. Cela fait <i>n</i> équations linéaires homogènes à <i>m</i> inconnues μⱼ, avec <i>m</i> &gt; <i>n</i>. Or un tel système a toujours une solution non nulle : en éliminant, chaque équation fixe au plus une inconnue en fonction des autres, et il reste au moins <i>m</i> − <i>n</i> ≥ 1 inconnue libre, qu’on peut prendre égale à 1. Les μⱼ obtenus ne sont pas tous nuls : la famille est liée. Pour la conséquence : si deux bases ont <i>n</i> et <i>n</i>′ éléments, la première est génératrice et la seconde libre, donc <i>n</i>′ ≤ <i>n</i> ; et symétriquement <i>n</i> ≤ <i>n</i>′.</p></div><div class="ex"><p>Dans ℝ³, (<b>e</b>₁, <b>e</b>₂, <b>e</b>₃) engendre : donc quatre vecteurs de ℝ³ sont toujours liés, et deux vecteurs n’engendrent jamais ℝ³ (sinon la famille libre (<b>e</b>₁, <b>e</b>₂, <b>e</b>₃) aurait au plus deux éléments).</p></div>'},
  {h:'Dimension',
   p:'<p>Puisque toutes les bases ont le même nombre d’éléments, ce nombre est une caractéristique de l’espace.</p><div class="def"><p>Si <i>E</i> possède une base finie, le nombre d’éléments de cette base (le même pour toutes) est la <b>dimension</b> de <i>E</i>, notée <b>dim <i>E</i></b>. On convient que dim {<b>0</b>} = 0 (sa base est la famille vide). Si aucune famille finie n’engendre <i>E</i>, on dit que <i>E</i> est de <b>dimension infinie</b>.</p></div><div class="ex"><p>dim ℝⁿ = <i>n</i> (base canonique à <i>n</i> vecteurs) ; dim ℝ² = 2, dim ℝ³ = 3. dim ℝ[<i>x</i>]≤ₙ = <i>n</i> + 1, car la base (1, <i>x</i>, …, <i>x</i>ⁿ) compte <i>n</i> + 1 polynômes : dim ℝ[<i>x</i>]≤₂ = 3. dim M₂(ℝ) = 4. Une droite vectorielle est de dimension 1, un plan vectoriel de dimension 2.</p></div><div class="ex"><p>ℝ[<i>x</i>] est de dimension infinie : une famille finie de polynômes a un degré maximal <i>d</i>, et ses combinaisons ne dépassent jamais le degré <i>d</i> ; <i>x</i><sup><i>d</i>+1</sup> n’est pas atteint. De même F(ℝ, ℝ) et l’espace des suites.</p></div><div class="idea"><p>La dimension compte le nombre de « degrés de liberté » : combien de nombres indépendants il faut pour repérer un vecteur. Elle ne dépend pas de la base choisie, grâce au lemme.</p></div><div class="warn"><p>Les polynômes de degré ≤ <i>n</i> forment un espace de dimension <i>n</i> + 1, pas <i>n</i> : on oublie souvent la constante. Et « les polynômes de degré exactement 2 » ne forment pas un espace vectoriel du tout (<i>x</i>² + (−<i>x</i>²) = 0 n’est pas de degré 2).</p></div>'},
  {h:'Le théorème de la base incomplète',
   p:'<p>Comment fabriquer des bases ? Deux chemins : partir d’une famille libre et l’agrandir, ou partir d’une famille génératrice et la dégraisser.</p><div class="thm"><p>Soit <i>E</i> de dimension finie <i>n</i>.<br>(1) <b>Base incomplète</b> : toute famille libre peut être complétée en une base, en lui ajoutant des vecteurs bien choisis.<br>(2) <b>Base extraite</b> : de toute famille génératrice on peut extraire une base, en retirant des vecteurs redondants.<br>(3) En dimension <i>n</i> : une famille <b>libre de <i>n</i> vecteurs</b> est une base ; une famille <b>génératrice de <i>n</i> vecteurs</b> est une base.</p></div><div class="why"><p>(1) Si la famille libre n’engendre pas <i>E</i>, il existe un vecteur <b>w</b> hors de son Vect ; on l’ajoute, et la famille reste libre (une relation nulle avec coefficient non nul devant <b>w</b> permettrait d’exprimer <b>w</b> avec les autres, contradiction). On recommence ; le lemme interdit de dépasser <i>n</i> vecteurs, donc le processus s’arrête sur une famille génératrice, qui est une base. (2) Si la famille génératrice est liée, un vecteur est combinaison des autres : on le retire sans changer Vect. On recommence jusqu’à obtenir une famille libre. (3) Une famille libre de <i>n</i> vecteurs se complète en une base, qui a <i>n</i> éléments : on n’a rien ajouté, c’était déjà une base. Même raisonnement en extrayant.</p></div><div class="ex"><p>Dans ℝ³, ((1 ; 1 ; 0), (0 ; 1 ; 1)) est libre. On ajoute <b>e</b>₁ = (1 ; 0 ; 0) : <i>a</i>(1 ; 1 ; 0) + <i>b</i>(0 ; 1 ; 1) + <i>c</i>(1 ; 0 ; 0) = <b>0</b> donne, par la troisième coordonnée, <i>b</i> = 0, puis <i>a</i> = 0 (deuxième), puis <i>c</i> = 0. Trois vecteurs libres en dimension 3 : c’est une base.</p></div>',
   note:'Le point (3) est un raccourci précieux : en dimension n, pour prouver qu’une famille de n vecteurs est une base, il suffit de vérifier UNE des deux conditions (libre ou génératrice), en général « libre », la plus facile.'},
  {kind:'Méthode',h:'Trouver une base et la dimension d’un sous-espace',
   p:'<b>Quand :</b> un sous-espace <i>F</i> est donné soit par des équations, soit par une famille qui l’engendre, et on veut une base et dim <i>F</i>. <b>Cas « équations » :</b> 1) résous le système en exprimant certaines inconnues en fonction des autres (les <b>paramètres</b>) ; 2) écris le vecteur général comme combinaison des paramètres : <b>w</b> = <i>s</i>·<b>a</b> + <i>t</i>·<b>b</b> ; 3) les vecteurs <b>a</b>, <b>b</b> engendrent <i>F</i> et sont libres (chaque paramètre apparaît seul dans une coordonnée) : c’est une base, et dim <i>F</i> = nombre de paramètres. <b>Cas « famille génératrice » :</b> teste si la famille est libre ; sinon, retire un vecteur qui s’exprime avec les autres, et recommence. La famille libre restante est une base (base extraite).',
   demo:{enonce:'1) Base et dimension de <i>F</i> = {(<i>x</i> ; <i>y</i> ; <i>z</i>) : <i>x</i> + <i>y</i> − 2<i>z</i> = 0}. 2) Base et dimension de <i>G</i> = Vect((1 ; 2 ; 3), (2 ; 1 ; 0), (3 ; 3 ; 3)).',
    etapes:[{f:'1) <i>x</i> = −<i>y</i> + 2<i>z</i> : les paramètres sont <i>y</i> et <i>z</i>.',w:'Une équation, trois inconnues : deux paramètres.'},
     {f:'(<i>x</i> ; <i>y</i> ; <i>z</i>) = (−<i>y</i> + 2<i>z</i> ; <i>y</i> ; <i>z</i>) = <i>y</i>(−1 ; 1 ; 0) + <i>z</i>(2 ; 0 ; 1).',w:'On sépare les termes en y et les termes en z.'},
     {f:'((−1 ; 1 ; 0), (2 ; 0 ; 1)) engendre <i>F</i> et est libre (deuxième coordonnée : <i>y</i> = 0 ; troisième : <i>z</i> = 0). Donc dim <i>F</i> = 2.',w:'F est un plan vectoriel.'},
     {f:'2) (3 ; 3 ; 3) = (1 ; 2 ; 3) + (2 ; 1 ; 0) : on le retire, Vect ne change pas.',w:'Vecteur redondant.'},
     {f:'((1 ; 2 ; 3), (2 ; 1 ; 0)) est libre (non colinéaires : 1 · 1 − 2 · 2 = −3 ≠ 0 sur les deux premières coordonnées). Base de <i>G</i>, dim <i>G</i> = 2.',w:'G est aussi un plan, engendré par deux vecteurs seulement.'}],
    conclusion:'dim <i>F</i> = 2 avec la base ((−1 ; 1 ; 0), (2 ; 0 ; 1)) ; dim <i>G</i> = 2 avec la base ((1 ; 2 ; 3), (2 ; 1 ; 0)). Règle empirique dans ℝⁿ : chaque équation indépendante fait perdre une dimension.'}},
  {h:'Dimension d’un sous-espace de ℝ⁴',p:'Quelle est la dimension de <i>F</i> = {(<i>x</i> ; <i>y</i> ; <i>z</i> ; <i>t</i>) ∈ ℝ⁴ : <i>x</i> + <i>y</i> = 0 et <i>z</i> − 2<i>t</i> = 0}&nbsp;?',lab:'dim F =',ans:2,
   why:'y = −x et z = 2t : (x ; y ; z ; t) = x(1 ; −1 ; 0 ; 0) + t(0 ; 0 ; 2 ; 1). Deux paramètres, deux vecteurs libres : dim F = 2.'},
  {h:'Dimension d’un sous-espace et formule de Grassmann',
   p:'<div class="prop"><p>Si <i>F</i> est un sous-espace de <i>E</i>, avec dim <i>E</i> = <i>n</i>, alors <i>F</i> est de dimension finie et <b>dim <i>F</i> ≤ <i>n</i></b>, avec <b>égalité si et seulement si <i>F</i> = <i>E</i></b>.</p></div><div class="why"><p>Une famille libre de <i>F</i> est libre dans <i>E</i>, donc a au plus <i>n</i> éléments (lemme) : on peut choisir une famille libre de <i>F</i> la plus grande possible, elle engendre <i>F</i> (sinon on pourrait l’agrandir), c’est une base, et dim <i>F</i> ≤ <i>n</i>. Si dim <i>F</i> = <i>n</i>, une base de <i>F</i> est une famille libre de <i>n</i> vecteurs de <i>E</i>, donc une base de <i>E</i> : <i>F</i> = <i>E</i>.</p></div><div class="thm"><p><b>Formule de Grassmann.</b> Pour deux sous-espaces <i>F</i>, <i>G</i> de dimension finie :<br><b>dim(<i>F</i> + <i>G</i>) = dim <i>F</i> + dim <i>G</i> − dim(<i>F</i> ∩ <i>G</i>)</b>.<br>En particulier, si la somme est directe, dim(<i>F</i> ⊕ <i>G</i>) = dim <i>F</i> + dim <i>G</i>.</p></div><div class="why"><p>Idée : on part d’une base de <i>F</i> ∩ <i>G</i> (disons <i>p</i> vecteurs). On la complète en une base de <i>F</i> (<i>p</i> + <i>a</i> vecteurs) et, séparément, en une base de <i>G</i> (<i>p</i> + <i>b</i> vecteurs). La réunion de ces vecteurs, sans répéter ceux de l’intersection, engendre <i>F</i> + <i>G</i> et on vérifie qu’elle est libre : elle compte <i>p</i> + <i>a</i> + <i>b</i> = (<i>p</i> + <i>a</i>) + (<i>p</i> + <i>b</i>) − <i>p</i> vecteurs. C’est la formule.</p></div><div class="ex"><p>Deux plans <i>F</i>, <i>G</i> distincts de ℝ³ : dim(<i>F</i> + <i>G</i>) ≤ 3 et dim <i>F</i> + dim <i>G</i> = 4, donc dim(<i>F</i> ∩ <i>G</i>) ≥ 1 : ils se coupent au moins selon une droite, comme annoncé. Et puisque <i>F</i> ≠ <i>G</i>, <i>F</i> + <i>G</i> est strictement plus grand que <i>F</i>, donc de dimension 3, et dim(<i>F</i> ∩ <i>G</i>) = 2 + 2 − 3 = 1 : exactement une droite.</p></div>',
   note:'Pour que F et G soient supplémentaires dans E, il faut et il suffit que F ∩ G = {0} et dim F + dim G = dim E : la formule donne alors dim(F + G) = dim E, donc F + G = E.'},
  {h:'Grassmann en dimension 5',p:'Dans un espace <i>E</i> de dimension 5, <i>F</i> est de dimension 3 et <i>G</i> de dimension 4. Que peut-on affirmer sur dim(<i>F</i> ∩ <i>G</i>)&nbsp;?',
   opts:['Elle vaut au moins 2','Elle vaut exactement 2','Elle peut être nulle','Elle vaut au moins 1, sans plus'],ans:0,
   why:'dim(F ∩ G) = 3 + 4 − dim(F + G) et dim(F + G) ≤ 5, donc dim(F ∩ G) ≥ 2. Elle vaut 2 si F + G = E, et 3 si F ⊂ G. Jamais moins de 2.'},
  {kind:'Récapitulatif',h:'Ce qu’il faut retenir',
   p:'<div class="keep"><ul><li>Génératrice : Vect(<b>v</b>₁, …, <b>v</b>ₖ) = <i>E</i>. Libre : λ₁<b>v</b>₁ + … + λₖ<b>v</b>ₖ = <b>0</b> ⇒ tous les λᵢ nuls. Test : résoudre le système homogène. Liée ⇔ un vecteur est combinaison des autres.</li><li>Base = libre et génératrice. Les coordonnées dans une base existent et sont uniques (unicité grâce à la liberté). Bases canoniques : ℝⁿ, (1, <i>x</i>, …, <i>x</i>ⁿ), les <i>E</i>ᵢⱼ de M₂(ℝ).</li><li>Lemme : une famille libre a au plus autant d’éléments qu’une famille génératrice. Donc toutes les bases ont le même nombre d’éléments : la dimension.</li><li>dim ℝⁿ = <i>n</i>, dim ℝ[<i>x</i>]≤ₙ = <i>n</i> + 1, dim M₂(ℝ) = 4, dim {<b>0</b>} = 0, ℝ[<i>x</i>] et F(ℝ, ℝ) sont de dimension infinie.</li><li>Base incomplète : toute famille libre se complète en base ; de toute famille génératrice on extrait une base. En dimension <i>n</i>, <i>n</i> vecteurs libres forment une base, <i>n</i> vecteurs générateurs aussi.</li><li>Base d’un sous-espace défini par des équations : résoudre, faire apparaître les paramètres, un vecteur par paramètre. dim <i>F</i> ≤ dim <i>E</i>, égalité ⇔ <i>F</i> = <i>E</i>.</li><li>Grassmann : dim(<i>F</i> + <i>G</i>) = dim <i>F</i> + dim <i>G</i> − dim(<i>F</i> ∩ <i>G</i>). Supplémentaires ⇔ <i>F</i> ∩ <i>G</i> = {<b>0</b>} et dim <i>F</i> + dim <i>G</i> = dim <i>E</i>.</li></ul></div>'},
  {kind:'Problème',h:'Les polynômes qui s’annulent en 2',
   p:'Dans <i>E</i> = ℝ[<i>x</i>]≤₃, l’espace des polynômes de degré au plus 3 (dim <i>E</i> = 4), on note <i>F</i> = {<i>P</i> ∈ <i>E</i> : <i>P</i>(2) = 0}. C’est un sous-espace (même preuve que pour <i>P</i>(1) = 0 au chapitre précédent). On cherche sa dimension, une base adaptée, les coordonnées d’un polynôme dans cette base, et un supplémentaire de <i>F</i>.',
   parts:[
    {q:'a) Lequel de ces polynômes appartient à <i>F</i>&nbsp;?',opts:['<i>x</i>² − 4','<i>x</i>² + 4','<i>x</i> − 1','2<i>x</i>'],ans:0,hint:'Évalue chaque polynôme en 2.',why:'2² − 4 = 0. Les autres valent 8, 1 et 4 en x = 2.'},
    {q:'b) En écrivant <i>P</i> = <i>a</i> + <i>bx</i> + <i>cx</i>² + <i>dx</i>³ et <i>P</i>(2) = 0, on exprime <i>a</i> = −2<i>b</i> − 4<i>c</i> − 8<i>d</i>, donc <i>P</i> = <i>b</i>(<i>x</i> − 2) + <i>c</i>(<i>x</i>² − 4) + <i>d</i>(<i>x</i>³ − 8). Quelle est la dimension de <i>F</i>&nbsp;?',lab:'dim F =',ans:3,hint:'Compte les paramètres, et vérifie que les trois polynômes sont libres (degrés 1, 2, 3 distincts).',why:'Trois paramètres b, c, d, et la famille (x − 2, x² − 4, x³ − 8) est libre : une combinaison nulle a un coefficient de x³ égal à d, donc d = 0, puis c = 0, puis b = 0. dim F = 3.'},
    {q:'c) Pourquoi la famille (<i>x</i> − 2, (<i>x</i> − 2)², (<i>x</i> − 2)³) est-elle aussi une base de <i>F</i>&nbsp;?',opts:['Parce qu’elle contient trois polynômes','Ses trois polynômes sont dans <i>F</i>, de degrés 1, 2, 3 distincts donc libres, et dim <i>F</i> = 3 : trois vecteurs libres en dimension 3 forment une base','Parce que (<i>x</i> − 2)³ = <i>x</i>³ − 8','Parce que toute famille de polynômes qui s’annulent en 2 est une base de <i>F</i>'],ans:1,
     hint:'Utilise le point (3) du théorème de la base incomplète.',why:'Chaque (x − 2)ᵏ vaut 0 en 2. Les degrés distincts donnent la liberté (on annule le coefficient dominant en premier). Libre de 3 vecteurs dans un espace de dimension 3 : base.'},
    {q:'d) Dans la base (<i>x</i> − 2, (<i>x</i> − 2)², (<i>x</i> − 2)³), quelle est la deuxième coordonnée (devant (<i>x</i> − 2)²) de <i>P</i> = <i>x</i>³ − 8&nbsp;?',lab:'coordonnée =',ans:6,hint:'Pose y = x − 2, donc x = y + 2, et développe (y + 2)³ − 8.',why:'(y + 2)³ − 8 = y³ + 6y² + 12y + 8 − 8 = y³ + 6y² + 12y. Coordonnées (12 ; 6 ; 1) : la deuxième vaut 6.'},
    {q:'e) Soit <i>C</i> = Vect(1) l’ensemble des polynômes constants. Pourquoi <i>F</i> et <i>C</i> sont-ils supplémentaires dans <i>E</i>&nbsp;?',opts:['Parce que 1 ∉ <i>F</i>','Une constante <i>c</i> est dans <i>F</i> seulement si <i>c</i> = 0, donc <i>F</i> ∩ <i>C</i> = {0}, et dim <i>F</i> + dim <i>C</i> = 3 + 1 = 4 = dim <i>E</i>','Parce que tout polynôme est constant ou s’annule en 2','Parce que dim <i>C</i> = 1'],ans:1,
     hint:'Deux choses à vérifier : l’intersection, et les dimensions (note du cours sur Grassmann).',why:'F ∩ C = {0} et dim F + dim C = dim E : par Grassmann, dim(F + C) = 4, donc F + C = E et la somme est directe. Concrètement, P = (P − P(2)) + P(2).'},
   ],
   sol:'<i>F</i> est un sous-espace de <i>E</i>. En résolvant <i>P</i>(2) = 0, on trouve <i>P</i> = <i>b</i>(<i>x</i> − 2) + <i>c</i>(<i>x</i>² − 4) + <i>d</i>(<i>x</i>³ − 8) : la famille (<i>x</i> − 2, <i>x</i>² − 4, <i>x</i>³ − 8) engendre <i>F</i> et elle est libre (degrés étagés), donc <b>dim <i>F</i> = 3</b>.<br>La famille (<i>x</i> − 2, (<i>x</i> − 2)², (<i>x</i> − 2)³) est formée de trois vecteurs de <i>F</i>, libres par leurs degrés : c’est une autre base de <i>F</i>. Avec <i>y</i> = <i>x</i> − 2, <i>x</i>³ − 8 = (<i>y</i> + 2)³ − 8 = 12<i>y</i> + 6<i>y</i>² + <i>y</i>³ : coordonnées (12 ; 6 ; 1).<br>Enfin <i>F</i> ∩ Vect(1) = {0} (une constante nulle en 2 est nulle) et 3 + 1 = 4 = dim <i>E</i> : <b><i>E</i> = <i>F</i> ⊕ Vect(1)</b>. La décomposition explicite est <i>P</i> = (<i>P</i> − <i>P</i>(2)) + <i>P</i>(2).'},
  {kind:'Problème',h:'Deux plans de l’espace',
   p:'Dans ℝ³, on considère le plan <i>F</i> d’équation <i>x</i> + <i>y</i> + <i>z</i> = 0 et le plan <i>G</i> = Vect((1 ; 0 ; 1), (0 ; 1 ; 1)). On veut déterminer dim(<i>F</i> + <i>G</i>) et dim(<i>F</i> ∩ <i>G</i>) grâce à la formule de Grassmann, puis trouver explicitement la droite <i>F</i> ∩ <i>G</i>, et décider si <i>F</i> et <i>G</i> sont supplémentaires.',
   parts:[
    {q:'a) Quelle est la dimension de <i>G</i>&nbsp;?',lab:'dim G =',ans:2,hint:'Les deux vecteurs sont-ils colinéaires ?',why:'(1 ; 0 ; 1) et (0 ; 1 ; 1) ne sont pas colinéaires (aucun n’est multiple de l’autre) : famille libre de deux vecteurs, base de G, dim G = 2.'},
    {q:'b) Que vaut dim(<i>F</i> + <i>G</i>)&nbsp;?',opts:['2, car <i>F</i> = <i>G</i>','4, car 2 + 2 = 4','3, car (1 ; 0 ; 1) ∈ <i>G</i> n’est pas dans <i>F</i>, donc <i>F</i> + <i>G</i> est strictement plus grand que <i>F</i>, et dim(<i>F</i> + <i>G</i>) ≤ 3','On ne peut pas savoir'],ans:2,
     hint:'Teste si (1 ; 0 ; 1) vérifie x + y + z = 0, puis utilise dim F < dim(F + G) ≤ dim ℝ³.',why:'1 + 0 + 1 = 2 ≠ 0, donc G ⊄ F et F + G contient strictement F : dim(F + G) ≥ 3. Comme F + G ⊂ ℝ³, dim(F + G) = 3 et F + G = ℝ³.'},
    {q:'c) D’après la formule de Grassmann, que vaut dim(<i>F</i> ∩ <i>G</i>)&nbsp;?',lab:'dim(F ∩ G) =',ans:1,hint:'dim(F ∩ G) = dim F + dim G − dim(F + G).',why:'2 + 2 − 3 = 1 : F ∩ G est une droite vectorielle.'},
    {q:'d) Un vecteur de <i>G</i> s’écrit <i>a</i>(1 ; 0 ; 1) + <i>b</i>(0 ; 1 ; 1) = (<i>a</i> ; <i>b</i> ; <i>a</i> + <i>b</i>). Le vecteur directeur de <i>F</i> ∩ <i>G</i> de première coordonnée 1 a pour deuxième coordonnée&nbsp;?',lab:'y =',ans:-1,hint:'Impose x + y + z = 0 à (a ; b ; a + b).',why:'a + b + (a + b) = 2(a + b) = 0, donc b = −a. Avec a = 1 : (1 ; −1 ; 0). Contrôle : 1 − 1 + 0 = 0, et (1 ; −1 ; 0) = (1 ; 0 ; 1) − (0 ; 1 ; 1) ∈ G.'},
    {q:'e) <i>F</i> et <i>G</i> sont-ils supplémentaires dans ℝ³&nbsp;?',opts:['Oui, car <i>F</i> + <i>G</i> = ℝ³','Oui, car dim <i>F</i> + dim <i>G</i> ≥ 3','Non, car <i>F</i> ∩ <i>G</i> ≠ {<b>0</b>} : la somme n’est pas directe','Non, car <i>F</i> ≠ <i>G</i>'],ans:2,
     hint:'Supplémentaires demande deux choses : somme égale à ℝ³ ET intersection réduite à {0}.',why:'La somme vaut bien ℝ³, mais l’intersection est une droite : la somme n’est pas directe. D’ailleurs 2 + 2 = 4 ≠ 3 : deux plans de ℝ³ ne sont jamais supplémentaires.'},
   ],
   sol:'<i>G</i> est engendré par deux vecteurs non colinéaires : dim <i>G</i> = 2. <i>F</i> est un plan : dim <i>F</i> = 2 (base ((−1 ; 1 ; 0), (−1 ; 0 ; 1))).<br>(1 ; 0 ; 1) ∉ <i>F</i>, donc <i>F</i> ⊊ <i>F</i> + <i>G</i> ⊂ ℝ³ et dim(<i>F</i> + <i>G</i>) = 3. Grassmann : dim(<i>F</i> ∩ <i>G</i>) = 2 + 2 − 3 = <b>1</b>.<br>Explicitement, (<i>a</i> ; <i>b</i> ; <i>a</i> + <i>b</i>) ∈ <i>F</i> ⇔ 2(<i>a</i> + <i>b</i>) = 0 ⇔ <i>b</i> = −<i>a</i> : <b><i>F</i> ∩ <i>G</i> = ℝ(1 ; −1 ; 0)</b>.<br><i>F</i> + <i>G</i> = ℝ³ mais <i>F</i> ∩ <i>G</i> ≠ {<b>0</b>} : la somme n’est pas directe, <i>F</i> et <i>G</i> ne sont pas supplémentaires. Un supplémentaire d’un plan de ℝ³ est toujours une droite (dimension 3 − 2 = 1).'},
]},
);
})();
